  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Connection flow (browser)
 18→ *
 19→ * On browser connect, the server sends two small messages:
 20→ * 1. `agent_list`  — metadata for all agents (sidebar).
 21→ * 2. `task_list`   — all tasks.
 22→ *
 23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
 24→ * browser sends `{ type: "request_history", agentId }` when the user
 25→ * selects an agent, and the server responds with `message_history` for
 26→ * that single agent. This avoids sending megabytes of JSON on connect,
 27→ * which caused multi-minute loading times on mobile networks.
 28→ *
 29→ * Live messages for active agents are still broadcast to all browsers
 30→ * via `relay` messages in real time.
 31→ *
 32→ * ## Message flow (spawning)
 33→ *
 34→ * 1. Browser sends `{ type: "spawn", prompt }`.
 35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 42→ *
 43→ * ## Resilience features
 44→ *
 45→ * - **Server-side message history** — every relay message is stored per-agent.
 46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 49→ *   can reconnect to the new server if they retry their WebSocket connection.
 50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
 53→ */
 54→import { WebSocketServer, WebSocket } from "ws";
 55→import { execSync, spawn } from "child_process";
 56→import { randomBytes } from "crypto";
 57→import type { IncomingMessage } from "http";
 58→import type {
 59→  BrowserMessage,
 60→  ClaudeMessage,
 61→  ServerMessage,
 62→  AgentStatus,
 63→  AgentInfo,
 64→  Task,
 65→} from "../lib/types";
 66→import { SessionStore, type PersistedAgent } from "./session-store";
 67→import { TaskStore } from "./task-store";
 68→
 69→const PORT = 9900;
 70→const TMUX_SESSION_PREFIX = "thos-agent";
 71→
 72→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 73→function isAllowedIP(ip: string | undefined): boolean {
 74→  if (!ip) return false;
 75→  // Strip IPv6-mapped IPv4 prefix
 76→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 77→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 78→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
 79→  const parts = addr.split(".");
 80→  if (parts.length !== 4) return false;
 81→  const first = parseInt(parts[0], 10);
 82→  const second = parseInt(parts[1], 10);
 83→  return first === 100 && second >= 64 && second <= 127;
 84→}
 85→
 86→const wss = new WebSocketServer({
 87→  port: PORT,
 88→  verifyClient: (info) => {
 89→    const ip = info.req.socket.remoteAddress;
 90→    const allowed = isAllowedIP(ip);
 91→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
 92→    return allowed;
 93→  },
 94→});
 95→const store = new SessionStore();
 96→
 97→// ── Multi-agent state ──────────────────────────────────────────────────────
 98→
 99→interface AgentState {
100→  agentId: string;
101→  claudeSocket: WebSocket | null;
102→  tmuxSession: string | null;
103→  pendingPrompt: string | null;
104→  status: AgentStatus;
105→  label: string;
106→  createdAt: number;
107→  /** Captured from system/init, used in subsequent user messages. */
108→  sessionId: string | null;
109→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
110→  pendingControlRequests: Map<string, Record<string, unknown>>;
111→  /** All messages sent to the browser for this agent (source of truth). */
112→  messageHistory: ServerMessage[];
113→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
114→  pendingMessages: string[];
115→}
116→
117→const agents = new Map<string, AgentState>();
118→const taskStore = new TaskStore();
119→const tasks = new Map<string, Task>();
120→
121→/** All active browser connections (supports multiple tabs). */
122→const browserSockets = new Set<WebSocket>();
123→
124→/** Generate a short random agent ID. */
125→function newAgentId(): string {
126→  return randomBytes(4).toString("hex");
127→}
128→
129→// ── tmux helpers ───────────────────────────────────────────────────────────
130→
131→/** Return the set of currently alive tmux session names matching the thos prefix. */
132→function listAliveTmuxSessions(): Set<string> {
133→  try {
134→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
135→      encoding: "utf-8",
136→    }).trim();
137→    if (!output) return new Set();
138→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
139→  } catch {
140→    return new Set();
141→  }
142→}
143→
144→// ── Persistence helpers ────────────────────────────────────────────────────
145→
146→/** Build a PersistedAgent snapshot from live state. */
147→function toPersistedAgent(agent: AgentState): PersistedAgent {
148→  return {
149→    id: agent.agentId,
150→    state: {
151→      agentId: agent.agentId,
152→      status: agent.status,
153→      tmuxSession: agent.tmuxSession,
154→      label: agent.label,
155→      createdAt: agent.createdAt,
156→      sessionId: agent.sessionId,
157→    },
158→    messageHistory: agent.messageHistory,
159→  };
160→}
161→
162→/** Persist agent state (debounced — use for streaming events). */
163→function persistAgent(agent: AgentState) {
164→  store.save(toPersistedAgent(agent));
165→}
166→
167→/** Persist agent state immediately (use for critical state changes). */
168→function persistAgentSync(agent: AgentState) {
169→  store.saveSync(toPersistedAgent(agent));
170→}
171→
172→// ── Restore from disk on startup ───────────────────────────────────────────
173→
174→function restoreAgents() {
175→  const persisted = store.loadAll();
176→  const aliveSessions = listAliveTmuxSessions();
177→
178→  for (const p of persisted) {
179→    const agent: AgentState = {
180→      agentId: p.state.agentId,
181→      claudeSocket: null,
182→      tmuxSession: p.state.tmuxSession,
183→      pendingPrompt: null,
184→      status: p.state.status,
185→      label: p.state.label,
186→      createdAt: p.state.createdAt,
187→      sessionId: p.state.sessionId,
188→      pendingControlRequests: new Map(),
189→      messageHistory: p.messageHistory,
190→      pendingMessages: [],
191→    };
192→
193→    // Determine status for agents that were active when the server last ran
194→    if (agent.status !== "done" && agent.status !== "error") {
195→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
196→      if (tmuxAlive) {
197→        // tmux session still alive — CLI may reconnect to this server
198→        agent.status = "disconnected";
199→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
200→      } else {
201→        // tmux session gone — agent is archived
202→        agent.status = "done";
203→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
204→      }
205→    }
206→
207→    agents.set(agent.agentId, agent);
208→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${agent.messageHistory.length} messages)`);
209→  }
210→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
211→}
212→
213→restoreAgents();
214→
215→// ── Task restore + helpers ────────────────────────────────────────────────
216→
217→function restoreTasks() {
218→  const persisted = taskStore.loadAll();
219→  for (const t of persisted) {
220→    tasks.set(t.id, t);
221→  }
222→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
223→}
224→
225→restoreTasks();
226→
227→/** Build the full task list sorted by creation time (newest first). */
228→function buildTaskList(): Task[] {
229→  return Array.from(tasks.values()).sort((a, b) => b.createdAt - a.createdAt);
230→}
231→
232→/** Send the full task list to all browsers. */
233→function broadcastTaskList() {
234→  const payload = JSON.stringify({ type: "task_list", tasks: buildTaskList() });
235→  for (const ws of browserSockets) {
236→    if (ws.readyState === WebSocket.OPEN) {
237→      ws.send(payload);
238→    }
239→  }
240→}
241→
242→/** Persist all tasks to disk (sync). */
243→function persistTasks() {
244→  taskStore.saveSync(Array.from(tasks.values()));
245→}
246→
247→// ── Helpers ────────────────────────────────────────────────────────────────
248→
249→/** Send a JSON message to all connected browsers. */
250→function sendToBrowser(msg: ServerMessage) {
251→  const payload = JSON.stringify(msg);
252→  for (const ws of browserSockets) {
253→    if (ws.readyState === WebSocket.OPEN) {
254→      ws.send(payload);
255→    }
256→  }
257→}
258→
259→/** Build a snapshot of all agents for the sidebar. */
260→function buildAgentList(): AgentInfo[] {
261→  return Array.from(agents.values()).map((a) => ({
262→    agentId: a.agentId,
263→    status: a.status,
264→    tmuxSession: a.tmuxSession,
265→    label: a.label,
266→    createdAt: a.createdAt,
267→  }));
268→}
269→
270→/** Send the full agent list to all browsers. */
271→function broadcastAgentList() {
272→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
273→}
274→
275→/** Update an agent's status, notify browsers, broadcast list, and persist. */
276→function setAgentStatus(agentId: string, status: AgentStatus) {
277→  const agent = agents.get(agentId);
278→  if (!agent) return;
279→  agent.status = status;
280→  sendToBrowser({ type: "status", agentId, status });
281→  broadcastAgentList();
282→  persistAgentSync(agent);
283→}
284→
285→/**
286→ * Record a message in the agent's history and send to all browsers.
287→ * This is used for relay messages so that message history is the source of truth.
288→ */
289→function recordAndSend(agentId: string, msg: ServerMessage) {
290→  const agent = agents.get(agentId);
291→  if (agent) {
292→    agent.messageHistory.push(msg);
293→    persistAgent(agent); // debounced — streaming messages come fast
294→  }
295→  sendToBrowser(msg);
296→}
297→
298→// ── Agent lifecycle ────────────────────────────────────────────────────────
299→
300→/**
301→ * Stop a running agent by killing its tmux session and closing the CLI socket.
302→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
303→ */
304→function stopAgent(agentId: string) {
305→  const agent = agents.get(agentId);
306→  if (!agent) return;
307→
308→  if (agent.tmuxSession) {
309→    try {
310→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
311→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
312→    } catch {
313→      // Session may already be dead
314→    }
315→  }
316→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
317→    agent.claudeSocket.close();
318→  }
319→  agent.claudeSocket = null;
320→  setAgentStatus(agentId, "done");
321→}
322→
323→/**
324→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
325→ */
326→function deleteAgent(agentId: string) {
327→  const agent = agents.get(agentId);
328→  if (!agent) return;
329→
330→  if (agent.tmuxSession) {
331→    try {
332→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
333→    } catch {}
334→  }
335→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
336→    agent.claudeSocket.close();
337→  }
338→  agents.delete(agentId);
339→  store.remove(agentId);
340→  broadcastAgentList();
341→}
342→
343→/**
344→ * Spawn a new Claude CLI process inside a tmux session.
345→ *
346→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
347→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
348→ */
349→function spawnClaude(prompt: string): string {
350→  const agentId = newAgentId();
351→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
352→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
353→
354→  const agent: AgentState = {
355→    agentId,
356→    claudeSocket: null,
357→    tmuxSession: null,
358→    pendingPrompt: prompt,
359→    status: "spawning",
360→    label,
361→    createdAt: Date.now(),
362→    sessionId: null,
363→    pendingControlRequests: new Map(),
364→    messageHistory: [],
365→    pendingMessages: [],
366→  };
367→  agents.set(agentId, agent);
368→
369→  // Notify browsers
370→  sendToBrowser({ type: "spawned", agentId });
371→  broadcastAgentList();
372→  persistAgentSync(agent);
373→
374→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
375→  // tmux new-session runs detached (-d) so spawn() returns immediately.
376→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
377→
378→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
379→    stdio: "ignore",
380→  });
381→
382→  tmux.on("error", (err) => {
383→    console.error("[tmux spawn error]", err);
384→    setAgentStatus(agentId, "error");
385→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
386→  });
387→
388→  tmux.on("exit", (code) => {
389→    if (code !== 0) {
390→      console.error(`[tmux] new-session exited with code ${code}`);
391→      setAgentStatus(agentId, "error");
392→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
393→      return;
394→    }
395→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
396→    agent.tmuxSession = sessionName;
397→    broadcastAgentList();
398→    persistAgentSync(agent);
399→  });
400→
401→  return agentId;
402→}
403→
404→// ── Message handlers ───────────────────────────────────────────────────────
405→
406→/**
407→ * Process an incoming NDJSON message from a specific Claude CLI.
408→ *
409→ * Status flow matches the Companion protocol:
410→ * - hook_response → send pending prompt → "thinking"
411→ * - system/init   → "connected" + capture session_id
412→ * - assistant      → "thinking"
413→ * - result         → "connected" (CLI stays alive for multi-turn)
414→ * - CLI disconnect → "done" (handled in connection close handler)
415→ */
416→function handleClaudeMessage(agentId: string, raw: string) {
417→  const agent = agents.get(agentId);
418→  if (!agent) return;
419→
420→  let msg: ClaudeMessage;
421→  try {
422→    msg = JSON.parse(raw);
423→  } catch {
424→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
425→    return;
426→  }
427→
428→  // Silently ignore keep_alive messages
429→  if (msg.type === "keep_alive") return;
430→
431→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
432→
433→  // After hook_response, send the pending prompt
434→  if (
435→    msg.type === "system" &&
436→    (msg as { subtype?: string }).subtype === "hook_response" &&
437→    agent.pendingPrompt &&
438→    agent.claudeSocket?.readyState === WebSocket.OPEN
439→  ) {
440→    const userMsg = JSON.stringify({
441→      type: "user",
442→      message: { role: "user", content: agent.pendingPrompt },
443→      parent_tool_use_id: null,
444→      session_id: agent.sessionId ?? "",
445→    });
446→    console.log(`[server → claude:${agentId}]`, userMsg);
447→    agent.claudeSocket.send(userMsg + "\n");
448→    agent.pendingPrompt = null;
449→    setAgentStatus(agentId, "thinking");
450→  }
451→
452→  // Track status based on message type
453→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
454→    // Capture session_id for subsequent user messages
455→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
456→    setAgentStatus(agentId, "connected");
457→  } else if (msg.type === "assistant") {
458→    setAgentStatus(agentId, "thinking");
459→  } else if (msg.type === "result") {
460→    // CLI stays alive after result — ready for the next turn.
461→    // Status only goes to "done" when the CLI WebSocket actually closes.
462→    setAgentStatus(agentId, "connected");
463→  }
464→
465→  // Store control_request inputs for building proper responses later
466→  if (msg.type === "control_request") {
467→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
468→    if (cr.request_id && cr.request?.input) {
469→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
470→    }
471→  }
472→
473→  // Record in history and relay to browsers
474→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
475→}
476→
477→/**
478→ * Process an incoming JSON message from the browser.
479→ * - `spawn`: create a new agent (does NOT kill others).
480→ * - `send_message`: forward a follow-up user message to the specified agent.
481→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
482→ * - `kill_agent`: stop the CLI and tmux session.
483→ * - `delete_agent`: permanently remove an agent.
484→ * - `rename_agent`: update an agent's label.
485→ * - `clear_history`: wipe an agent's message history.
486→ * - `request_history`: send message history for a single agent (lazy loading).
487→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
488→ */
489→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
490→  let msg: BrowserMessage;
491→  try {
492→    msg = JSON.parse(raw);
493→  } catch {
494→    console.error("[browser] invalid JSON:", raw);
495→    return;
496→  }
497→
498→  console.log("[browser →]", msg.type);
499→
500→  switch (msg.type) {
501→    case "spawn":
502→      spawnClaude(msg.prompt);
503→      break;
504→
505→    case "send_message": {
506→      const agent = agents.get(msg.agentId);
507→      if (!agent) {
508→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
509→        break;
510→      }
511→
512→      // Record the user message in history so it persists across reloads
513→      recordAndSend(msg.agentId, {
514→        type: "relay",
515→        agentId: msg.agentId,
516→        message: { type: "user", message: { role: "user", content: msg.content } },
517→      });
518→
519→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
520→        const userMsg = JSON.stringify({
521→          type: "user",
522→          message: { role: "user", content: msg.content },
523→          parent_tool_use_id: null,
524→          session_id: agent.sessionId ?? "",
525→        });
526→        agent.claudeSocket.send(userMsg + "\n");
527→        setAgentStatus(msg.agentId, "thinking");
528→      } else {
529→        // Queue message for delivery when CLI reconnects
530→        const userMsg = JSON.stringify({
531→          type: "user",
532→          message: { role: "user", content: msg.content },
533→          parent_tool_use_id: null,
534→          session_id: agent.sessionId ?? "",
535→        });
536→        agent.pendingMessages.push(userMsg);
537→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
538→        persistAgentSync(agent);
539→      }
540→      break;
541→    }
542→
543→    case "control_response": {
544→      const agent = agents.get(msg.agentId);
545→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
546→        // Retrieve the original tool input to include as updatedInput (required by protocol)
547→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
548→        agent.pendingControlRequests.delete(msg.request_id);
549→
550→        // If the browser sent answers (from AskUserQuestion), merge them into the input
551→        const answers = (msg as { answers?: Record<string, string> }).answers;
552→        const updatedInput = answers
553→          ? { ...originalInput, answers }
554→          : originalInput;
555→
556→        const response = JSON.stringify({
557→          type: "control_response",
558→          response: {
559→            subtype: "success",
560→            request_id: msg.request_id,
561→            response: msg.allow
562→              ? { behavior: "allow", updatedInput }
563→              : { behavior: "deny", message: "Denied by user" },
564→          },
565→        });
566→        agent.claudeSocket.send(response + "\n");
567→      }
568→      break;
569→    }
570→
571→    case "kill_agent":
572→      stopAgent(msg.agentId);
573→      break;
574→
575→    case "delete_agent":
576→      deleteAgent(msg.agentId);
577→      break;
578→
579→    case "rename_agent": {
580→      const agent = agents.get(msg.agentId);
581→      if (!agent) break;
582→      agent.label = msg.label;
583→      broadcastAgentList();
584→      persistAgentSync(agent);
585→      break;
586→    }
587→
588→    case "clear_history": {
589→      const agent = agents.get(msg.agentId);
590→      if (!agent) break;
591→      agent.messageHistory = [];
592→      persistAgentSync(agent);
593→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
594→      break;
595→    }
596→
597→    case "request_history": {
598→      console.log(`[browser] request_history for ${msg.agentId}`);
599→      sendHistoryToSocket(senderWs, msg.agentId);
600→      break;
601→    }
602→
603→    case "create_task": {
604→      const taskId = randomBytes(4).toString("hex");
605→      const task: Task = {
606→        id: taskId,
607→        title: msg.title,
608→        description: msg.description,
609→        status: "todo",
610→        priority: msg.priority,
611→        agentId: null,
612→        createdAt: Date.now(),
613→        updatedAt: Date.now(),
614→      };
615→      tasks.set(taskId, task);
616→      persistTasks();
617→      broadcastTaskList();
618→      break;
619→    }
620→
621→    case "update_task": {
622→      const task = tasks.get(msg.taskId);
623→      if (!task) break;
624→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
625→      persistTasks();
626→      broadcastTaskList();
627→      break;
628→    }
629→
630→    case "delete_task": {
631→      tasks.delete(msg.taskId);
632→      persistTasks();
633→      broadcastTaskList();
634→      break;
635→    }
636→
637→    case "delegate_task": {
638→      const task = tasks.get(msg.taskId);
639→      if (!task) break;
640→      const prompt = `Task: ${task.title}\n\n${task.description}`;
641→      const agentId = spawnClaude(prompt);
642→      task.agentId = agentId;
643→      task.status = "in-progress";
644→      task.updatedAt = Date.now();
645→      persistTasks();
646→      broadcastTaskList();
647→      break;
648→    }
649→  }
650→}
651→
652→// ── Send message history to a single browser socket ────────────────────────
653→
654→/** Send initial state (agent list + tasks) to a newly connected browser. */
655→function sendFullStateToSocket(ws: WebSocket) {
656→  if (ws.readyState !== WebSocket.OPEN) return;
657→
658→  // Agent list (sidebar metadata) — message histories are loaded lazily on demand
659→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
660→
661→  // Task list
662→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList() }));
663→}
664→
665→/** Send message history for a single agent to a specific browser socket. */
666→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
667→  const agent = agents.get(agentId);
668→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
669→  ws.send(
670→    JSON.stringify({
671→      type: "message_history",
672→      agentId: agent.agentId,
673→      messages: agent.messageHistory,
674→    })
675→  );
676→}
677→
678→// ── Connection handler — route by URL path ────────────────────────────────
679→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
680→  const path = req.url ?? "/";
681→  console.log(`[ws connected] path=${path}`);
682→
