// ── UI state ──────────────────────────────────────────────────────────────

/**
 * Lifecycle states of the Claude agent process:
 * - `idle`      — no process running, ready to spawn
 * - `spawning`  — process launched, waiting for CLI to connect via WS
 * - `connected` — CLI connected and `system/init` received
 * - `thinking`  — waiting for assistant response
 * - `done`      — `result` message received, process finished
 * - `error`     — process crashed or unexpected failure
 */
export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";

export type ChatMessageRole = "user" | "assistant" | "system";

/**
 * A single entry in the chat message list. System messages include
 * session init info and result summaries. Messages with a `controlRequest`
 * are rendered as tool-approval cards instead of plain bubbles.
 */
/** A single option in an AskUserQuestion question. */
export interface UserQuestionOption {
  label: string;
  description?: string;
}

/** A single question from AskUserQuestion. */
export interface UserQuestion {
  question: string;
  header?: string;
  options: UserQuestionOption[];
  multiSelect: boolean;
}

/** Info about a single tool_use block in an assistant message. */
export interface ToolCallInfo {
  name: string;
  toolUseId?: string;
}

export interface ChatMessage {
  id: string;
  role: ChatMessageRole;
  content: string;
  timestamp: number;
  /** Present when this message represents a tool approval request. */
  controlRequest?: {
    id: string;
    tool_name: string;
    input: Record<string, unknown>;
    /** Set to true after the user allows or denies. */
    resolved?: boolean;
  };
  /** Present when this message is an AskUserQuestion control request. */
  userQuestion?: {
    requestId: string;
    questions: UserQuestion[];
    resolved?: boolean;
  };
  /** Tool calls found in this assistant message. */
  toolCalls?: ToolCallInfo[];
  /** True when this message has only tool_use/tool_result blocks and no text. */
  isToolOnly?: boolean;
}

// ── Task system ──────────────────────────────────────────────────────────

export type TaskStatus = "todo" | "in-progress" | "done";
export type TaskPriority = "low" | "medium" | "high" | "urgent";

/** A user-created task, optionally linked to a Claude agent. */
export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: TaskPriority;
  /** If delegated, the agentId of the spawned Claude agent. */
  agentId: string | null;
  createdAt: number;
  updatedAt: number;
}

"use client";

/**
 * Dashboard route (`/dashboard`).
 *
 * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
 * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
 * to `null`, which shows the spawn input. On spawn, the server responds
 * with `spawned` and the hook auto-selects the new agent.
 */

import { useEffect, useState } from "react";
import { useWebSocket } from "@/hooks/use-websocket";
import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
import { Chat } from "@/components/dashboard/chat";
import { TaskPanel } from "@/components/dashboard/task-panel";
import { cn } from "@/lib/utils";

export default function DashboardPage() {
  const {
    connected,
    initialLoadDone,
    historyLoading,
    agents,
    agentOrder,
    activeAgentId,
    setActiveAgentId,
    activeStatus,
    activeMessages,
    activeRawMessages,
    spawnAgent,
    sendMessage,
    respondToControl,
    respondToUserQuestion,
    killAgent,
    deleteAgent,
    renameAgent,
    clearHistory,
    tasks,
    createTask,
    updateTask,
    deleteTask,
    delegateTask,
  } = useWebSocket();

  const [showTasks, setShowTasks] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    document.title = "thos — dashboard";
  }, []);

  return (
    <div className="relative flex h-dvh overflow-hidden">
      {/* Sidebar backdrop (mobile only) */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 md:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar drawer */}
      <div
        className={cn(
          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
          sidebarOpen ? "translate-x-0" : "-translate-x-full"
        )}
      >
        <AgentSidebar
          agents={agents}
          agentOrder={agentOrder}
          activeAgentId={activeAgentId}
          loading={!initialLoadDone}
          onSelect={(id) => {
            setActiveAgentId(id);
            setSidebarOpen(false);
          }}
          onNewAgent={() => {
            setActiveAgentId(null);
            setSidebarOpen(false);
          }}
          onKill={killAgent}
          onDelete={deleteAgent}
          onRename={renameAgent}
          onClearHistory={clearHistory}
        />
      </div>

      {/* Main chat area */}
      <div className="flex min-w-0 flex-1 flex-col">
        <Chat
          connected={connected}
          loading={!initialLoadDone || historyLoading}
          status={activeStatus}
          messages={activeMessages}
          rawMessages={activeRawMessages}
          onSendMessage={sendMessage}
          onSpawnAgent={spawnAgent}
          onRespondToControl={respondToControl}
          onRespondToUserQuestion={respondToUserQuestion}
          showTasks={showTasks}
          onToggleTasks={() => setShowTasks((v) => !v)}
          onToggleSidebar={() => setSidebarOpen((v) => !v)}
        />
      </div>

      {/* Task panel backdrop (mobile only) */}
      {showTasks && (
        <div
          className="fixed inset-0 z-40 bg-black/50 md:hidden"
          onClick={() => setShowTasks(false)}
        />
      )}

      {/* Task panel drawer */}
      {showTasks && (
        <div
          className="fixed inset-y-0 right-0 z-50 w-80 max-w-[calc(100vw-3rem)] border-l bg-background flex flex-col md:relative md:z-auto md:max-w-none"
        >
          <TaskPanel
            tasks={tasks}
            onCreateTask={createTask}
            onUpdateTask={updateTask}
            onDeleteTask={deleteTask}
            onDelegateTask={delegateTask}
            onSelectAgent={(agentId) => {
              setActiveAgentId(agentId);
            }}
            onClose={() => setShowTasks(false)}
          />
        </div>
      )}
    </div>
  );
}

