  control_request: "text-orange-400",
  keep_alive: "text-muted-foreground",
};

function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
  const [expanded, setExpanded] = useState(false);
  const subtype = (message as { subtype?: string }).subtype;
  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";

  return (
    <div className="font-mono text-[11px] leading-relaxed">
      <button
        onClick={() => setExpanded((v) => !v)}
        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
      >
        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
        <span className={colorClass}>{typeLabel}</span>
        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
      </button>
      {expanded && (
        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
          {JSON.stringify(message, null, 2)}
        </pre>
      )}
    </div>
  );
}

content.text:
The server only sends `message_history` for agents that have messages:

`server/ws.ts:630-639`:
```ts
for (const agent of agents.values()) {
  if (agent.messageHistory.length > 0) {  // ← skips agents with no history
    ws.send(JSON.stringify({
      type: "message_history",
      agentId: agent.agentId,
      messages: agent.messageHistory,
    }));
  }
}
```

So agents with empty history just won't get a `message_history` message — that's expected.

But if you're seeing agents that *should* have messages but aren't getting their history, the issue is likely that the `ws.send()` calls are being buffered by the `ws` library and not all flushing before the browser processes them. On a slow network, Node's `ws.send()` is non-blocking — it queues into the kernel send buffer, and large payloads for agents with lots of messages could take time to actually transmit.

Check the console logs — do you see `message_history` log lines for the agents that are missing? If you see `agent_list` but no `message_history` lines at all, the messages might be getting dropped or the WS connection is closing before they arrive.

What do the `[thos-ws]` logs show? Specifically:
1. Do you see `← agent_list` followed by `← message_history` for each agent?
2. Or does it stop after `← agent_list`?

