 1→"use client";
 2→
 3→/**
 4→ * Top bar showing the WS connection state (green/red dot) and the
 5→ * current agent lifecycle status (idle, spawning, thinking, etc.).
 6→ */
 7→
 8→import { ListTodo } from "lucide-react";
 9→import { Button } from "@/components/ui/button";
10→import { cn } from "@/lib/utils";
11→import type { AgentStatus } from "@/lib/types";
12→
13→/** Human-readable labels for each agent status. */
14→const STATUS_LABELS: Record<AgentStatus, string> = {
15→  idle: "idle",
16→  spawning: "spawning...",
17→  connected: "connected",
18→  thinking: "thinking...",
19→  done: "done",
20→  disconnected: "disconnected",
21→  error: "error",
22→};
23→
24→export function StatusBar({
25→  connected,
26→  status,
27→  showRaw,
28→  onToggleRaw,
29→  showTasks,
30→  onToggleTasks,
31→}: {
32→  connected: boolean;
33→  status: AgentStatus;
34→  showRaw?: boolean;
35→  onToggleRaw?: () => void;
36→  showTasks?: boolean;
37→  onToggleTasks?: () => void;
