  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ */
 11→
 12→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 13→
 14→/**
 15→ * Sent once after the first user prompt is received. Contains session
 16→ * metadata like the model name, working directory, and available tools.
 17→ */
 18→export interface ClaudeSystemInit {
 19→  type: "system";
 20→  subtype: "init";
 21→  session_id: string;
 22→  tools: unknown[];
 23→  mcp_servers: unknown[];
 24→  model: string;
 25→  cwd: string;
 26→}
 27→
 28→/**
 29→ * An assistant turn. `message.content` is an array of content blocks
 30→ * (text, tool_use, tool_result) that may arrive incrementally — each
 31→ * NDJSON line is a complete snapshot of the message so far.
 32→ */
 33→export interface ClaudeAssistant {
 34→  type: "assistant";
 35→  message: {
 36→    id: string;
 37→    role: "assistant";
 38→    content: AssistantContentBlock[];
 39→    model: string;
 40→    stop_reason: string | null;
 41→  };
 42→  session_id: string;
 43→}
 44→
 45→/** A single content block inside an assistant message. */
 46→export type AssistantContentBlock =
 47→  | { type: "text"; text: string }
 48→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 49→  | { type: "tool_result"; tool_use_id: string; content: string };
 50→
 51→/**
 52→ * Terminal message for a session. Includes cost/duration metrics.
 53→ * `is_error` is true when `subtype` is `"error"`.
 54→ */
 55→export interface ClaudeResult {
 56→  type: "result";
 57→  subtype: "success" | "error";
 58→  result?: string;
 59→  error?: string;
 60→  session_id: string;
 61→  cost_usd: number;
 62→  duration_ms: number;
 63→  duration_api_ms: number;
 64→  is_error: boolean;
 65→  num_turns: number;
 66→}
 67→
 68→/**
 69→ * Claude is requesting permission to execute a tool. The dashboard must
 70→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 71→ *
 72→ * Wire format uses a nested `request` object with `request_id` at the
 73→ * top level for correlation (matches Companion protocol docs).
 74→ */
 75→export interface ClaudeControlRequest {
 76→  type: "control_request";
 77→  request_id: string;
 78→  request: {
 79→    subtype: "can_use_tool";
 80→    tool_name: string;
 81→    input: Record<string, unknown>;
 82→    tool_use_id?: string;
 83→    description?: string;
 84→  };
 85→  session_id?: string;
 86→}
 87→
 88→/**
 89→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
 90→ * the signal that the CLI is ready to receive the first user prompt.
 91→ */
 92→export interface ClaudeSystemHook {
 93→  type: "system";
 94→  subtype: "hook_started" | "hook_response";
 95→  session_id?: string;
 96→}
 97→
 98→/** Discriminated union of all known Claude NDJSON message shapes. */
 99→export type ClaudeMessage =
100→  | ClaudeSystemInit
101→  | ClaudeAssistant
102→  | ClaudeResult
103→  | ClaudeControlRequest
104→  | ClaudeSystemHook
105→  | { type: string; subtype?: string; [key: string]: unknown };
106→
107→// ── Browser ↔ Server messages ─────────────────────────────────────────────
108→
109→/** Browser asks the server to spawn a new Claude CLI process. */
110→export interface BrowserSpawn {
111→  type: "spawn";
112→  prompt: string;
113→}
114→
115→/** Browser sends a follow-up message to an already-running Claude session. */
116→export interface BrowserSendMessage {
117→  type: "send_message";
118→  agentId: string;
119→  content: string;
120→}
121→
122→/** Browser responds to a tool approval request (allow or deny). */
123→export interface BrowserControlResponse {
124→  type: "control_response";
125→  agentId: string;
126→  request_id: string;
127→  allow: boolean;
128→}
129→
130→/** Browser asks the server to kill a running agent's tmux session + CLI. */
131→export interface BrowserKillAgent {
132→  type: "kill_agent";
133→  agentId: string;
134→}
135→
136→/** Browser asks the server to permanently delete an agent. */
137→export interface BrowserDeleteAgent {
138→  type: "delete_agent";
139→  agentId: string;
140→}
141→
142→/** Browser asks the server to rename an agent. */
143→export interface BrowserRenameAgent {
144→  type: "rename_agent";
145→  agentId: string;
146→  label: string;
147→}
148→
149→/** Browser asks the server to clear an agent's message history. */
150→export interface BrowserClearHistory {
151→  type: "clear_history";
152→  agentId: string;
153→}
154→
155→/** Browser asks the server to create a new task. */
156→export interface BrowserCreateTask {
157→  type: "create_task";
158→  title: string;
159→  description: string;
160→  priority: TaskPriority;
161→}
162→
163→/** Browser asks to update a task's fields. */
164→export interface BrowserUpdateTask {
165→  type: "update_task";
166→  taskId: string;
167→  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
168→}
169→
170→/** Browser asks to delete a task. */
171→export interface BrowserDeleteTask {
172→  type: "delete_task";
173→  taskId: string;
174→}
175→
176→/** Browser asks to delegate a task to a new Claude agent. */
177→export interface BrowserDelegateTask {
178→  type: "delegate_task";
179→  taskId: string;
180→}
181→
182→/** Union of all messages the browser can send to the WS server. */
183→export type BrowserMessage =
184→  | BrowserSpawn
185→  | BrowserSendMessage
186→  | BrowserControlResponse
187→  | BrowserKillAgent
188→  | BrowserDeleteAgent
189→  | BrowserRenameAgent
190→  | BrowserClearHistory
191→  | BrowserCreateTask
192→  | BrowserUpdateTask
193→  | BrowserDeleteTask
194→  | BrowserDelegateTask;
195→
196→/** Server relays a raw Claude NDJSON message to the browser. */
197→export interface ServerRelay {
198→  type: "relay";
199→  agentId: string;
200→  message: ClaudeMessage;
201→}
202→
203→/** Server notifies the browser of an agent status change. */
204→export interface ServerStatus {
205→  type: "status";
206→  agentId: string;
207→  status: AgentStatus;
208→}
209→
210→/** Server reports an error (e.g. no active session, process crash). */
211→export interface ServerError {
212→  type: "error";
213→  agentId: string;
214→  error: string;
215→}
216→
217→/** Summary of an agent for the sidebar. */
218→export interface AgentInfo {
219→  agentId: string;
220→  status: AgentStatus;
221→  tmuxSession: string | null;
222→  label: string;
223→  createdAt: number;
224→}
225→
226→/** Server sends the full list of agents after every state change. */
227→export interface ServerAgentList {
228→  type: "agent_list";
229→  agents: AgentInfo[];
230→}
231→
232→/** Server confirms a new agent was spawned and assigns its ID. */
233→export interface ServerSpawned {
234→  type: "spawned";
235→  agentId: string;
236→}
237→
238→/** Server replays full message history for an agent on browser connect. */
239→export interface ServerMessageHistory {
240→  type: "message_history";
241→  agentId: string;
242→  messages: ServerMessage[];
243→}
244→
245→/** CLI WebSocket disconnected (process may have crashed or exited). */
246→export interface ServerCliDisconnected {
247→  type: "cli_disconnected";
248→  agentId: string;
249→}
250→
251→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
252→export interface ServerCliConnected {
253→  type: "cli_connected";
254→  agentId: string;
255→}
256→
257→/** Server confirms message history was cleared for an agent. */
258→export interface ServerHistoryCleared {
259→  type: "history_cleared";
260→  agentId: string;
261→}
262→
263→/** Server sends the full task list to the browser. */
264→export interface ServerTaskList {
265→  type: "task_list";
266→  tasks: Task[];
267→}
268→
269→/** Server confirms a task was updated. */
270→export interface ServerTaskUpdated {
271→  type: "task_updated";
272→  task: Task;
273→}
274→
275→/** Server confirms a task was deleted. */
276→export interface ServerTaskDeleted {
277→  type: "task_deleted";
278→  taskId: string;
279→}
280→
281→/** Union of all messages the WS server can send to the browser. */
282→export type ServerMessage =
283→  | ServerRelay
284→  | ServerStatus
285→  | ServerError
286→  | ServerAgentList
287→  | ServerSpawned
288→  | ServerMessageHistory
289→  | ServerCliDisconnected
290→  | ServerCliConnected
291→  | ServerHistoryCleared
292→  | ServerTaskList
293→  | ServerTaskUpdated
294→  | ServerTaskDeleted;
295→
296→// ── UI state ──────────────────────────────────────────────────────────────
297→
298→/**
299→ * Lifecycle states of the Claude agent process:
300→ * - `idle`      — no process running, ready to spawn
301→ * - `spawning`  — process launched, waiting for CLI to connect via WS
302→ * - `connected` — CLI connected and `system/init` received
303→ * - `thinking`  — waiting for assistant response
304→ * - `done`      — `result` message received, process finished
305→ * - `error`     — process crashed or unexpected failure
306→ */
307→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
308→
309→export type ChatMessageRole = "user" | "assistant" | "system";
310→
311→/**
312→ * A single entry in the chat message list. System messages include
313→ * session init info and result summaries. Messages with a `controlRequest`
314→ * are rendered as tool-approval cards instead of plain bubbles.
315→ */
316→/** A single option in an AskUserQuestion question. */
317→export interface UserQuestionOption {
318→  label: string;
319→  description?: string;
320→}
321→
322→/** A single question from AskUserQuestion. */
323→export interface UserQuestion {
324→  question: string;
325→  header?: string;
326→  options: UserQuestionOption[];
327→  multiSelect: boolean;
328→}
329→
330→/** Info about a single tool_use block in an assistant message. */
331→export interface ToolCallInfo {
332→  name: string;
333→  toolUseId?: string;
334→}
335→
336→export interface ChatMessage {
337→  id: string;
338→  role: ChatMessageRole;
339→  content: string;
340→  timestamp: number;
341→  /** Present when this message represents a tool approval request. */
342→  controlRequest?: {
343→    id: string;
344→    tool_name: string;
345→    input: Record<string, unknown>;
346→    /** Set to true after the user allows or denies. */
347→    resolved?: boolean;
348→  };
349→  /** Present when this message is an AskUserQuestion control request. */
350→  userQuestion?: {
351→    requestId: string;
352→    questions: UserQuestion[];
353→    resolved?: boolean;
354→  };
355→  /** Tool calls found in this assistant message. */
356→  toolCalls?: ToolCallInfo[];
357→  /** True when this message has only tool_use/tool_result blocks and no text. */
358→  isToolOnly?: boolean;
359→}
360→
361→// ── Task system ──────────────────────────────────────────────────────────
362→
363→export type TaskStatus = "todo" | "in-progress" | "done";
364→export type TaskPriority = "low" | "medium" | "high" | "urgent";
365→
366→/** A user-created task, optionally linked to a Claude agent. */
367→export interface Task {
368→  id: string;
369→  title: string;
370→  description: string;
371→  status: TaskStatus;
372→  priority: TaskPriority;
373→  /** If delegated, the agentId of the spawned Claude agent. */
374→  agentId: string | null;
375→  createdAt: number;
376→  updatedAt: number;
377→}
