268→      onClick={onClick}
269→      className={cn(
270→        "flex w-full px-3 py-1.5 text-xs transition-colors",
271→        destructive
272→          ? "text-red-500 hover:bg-red-500/10"
273→          : "hover:bg-accent"
274→      )}
275→    >
276→      {label}
