 10→
 11→interface TaskPanelProps {
 12→  tasks: Task[];
 13→  onCreateTask: (title: string, description: string, priority: TaskPriority) => void;
 14→  onUpdateTask: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
 15→  onDeleteTask: (taskId: string) => void;
 16→  onDelegateTask: (taskId: string) => void;
 17→  onSelectAgent: (agentId: string) => void;
 18→  onClose: () => void;
