    respondToUserQuestion,
    killAgent,
    deleteAgent,
    renameAgent,
    clearHistory,
    tasks,
    createTask,
    updateTask,
    deleteTask,
    delegateTask,
  } = useWebSocket();

  const [showTasks, setShowTasks] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    document.title = "thos — dashboard";
  }, []);

  return (
    <div className="flex h-dvh">
      <AgentSidebar
        agents={agents}
