  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * Resilience features:
 11→ * - Handles `message_history` replay from server on connect/reconnect.
 12→ * - Handles `cli_disconnected` / `cli_connected` events.
 13→ * - Deduplicates messages using a per-agent Set of seen message IDs.
 14→ * - Robust reconnection guard (clears previous timer before scheduling).
 15→ */
 16→
 17→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 18→import type {
 19→  AgentInfo,
 20→  AgentStatus,
 21→  ChatMessage,
 22→  ClaudeAssistant,
 23→  ClaudeControlRequest,
 24→  ClaudeMessage,
 25→  ClaudeResult,
 26→  ClaudeSystemInit,
 27→  ServerMessage,
 28→  ServerMessageHistory,
 29→  ServerTaskList,
 30→  ServerTaskUpdated,
 31→  ServerTaskDeleted,
 32→  Task,
 33→  TaskPriority,
 34→  ToolCallInfo,
 35→  UserQuestion,
 36→} from "@/lib/types";
 37→
 38→/** Connect to the WS server on the same host the page was loaded from. */
 39→const WS_URL =
 40→  typeof window !== "undefined"
 41→    ? `ws://${window.location.hostname}:9900/browser`
 42→    : "ws://localhost:9900/browser";
 43→
 44→/** Per-agent client state. */
 45→export interface AgentClientState {
 46→  status: AgentStatus;
 47→  messages: ChatMessage[];
 48→  /** Raw Claude NDJSON messages for debug view. */
 49→  rawMessages: ClaudeMessage[];
 50→  label: string;
 51→  tmuxSession: string | null;
 52→  createdAt: number;
 53→}
 54→
 55→/**
 56→ * Extract displayable text from a Claude assistant message.
 57→ * Content blocks may be text, tool_use, or tool_result — each is
 58→ * handled defensively since the array structure can vary.
 59→ */
 60→function extractText(msg: ClaudeAssistant): string {
 61→  const blocks = msg.message?.content;
 62→  if (!blocks || !Array.isArray(blocks)) return "";
 63→  return blocks
 64→    .map((b) => {
 65→      if (b.type === "text") return b.text;
 66→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 67→      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
 68→      return "";
 69→    })
 70→    .filter(Boolean)
 71→    .join("\n");
 72→}
 73→
 74→/** Module-level counter for generating unique message IDs. */
 75→let msgCounter = 0;
 76→function nextId() {
 77→  return `msg-${Date.now()}-${++msgCounter}`;
 78→}
 79→
 80→/**
 81→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 82→ * Used both for live messages and for replaying message_history.
 83→ */
 84→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
 85→  if (relayMsg.type === "relay") {
 86→    const msg = relayMsg.message;
 87→
 88→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 89→      const init = msg as ClaudeSystemInit;
 90→      return {
 91→        id: nextId(),
 92→        role: "system",
 93→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
 94→        timestamp: Date.now(),
 95→      };
 96→    }
 97→
 98→    if (msg.type === "assistant") {
 99→      const assistant = msg as ClaudeAssistant;
100→      const text = extractText(assistant);
101→      if (!text) return null;
102→
103→      const blocks = assistant.message?.content ?? [];
104→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
105→      const toolCalls: ToolCallInfo[] = blocks
106→        .filter((b) => b.type === "tool_use")
107→        .map((b) => ({
108→          name: (b as { name: string }).name,
109→          toolUseId: (b as { id: string }).id,
110→        }));
111→      const isToolOnly = !hasText && toolCalls.length > 0;
112→
113→      return {
114→        id: nextId(),
115→        role: "assistant",
116→        content: text,
117→        timestamp: Date.now(),
118→        toolCalls,
119→        isToolOnly,
120→      };
121→    }
122→
123→    if (msg.type === "result") {
124→      const result = msg as ClaudeResult;
125→      const summary = result.is_error
126→        ? `Error: ${result.error}`
127→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
128→      return {
129→        id: nextId(),
130→        role: "system",
131→        content: summary,
132→        timestamp: Date.now(),
133→      };
134→    }
135→
136→    if (msg.type === "control_request") {
137→      const cr = msg as ClaudeControlRequest;
138→
139→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
140→      if (cr.request.tool_name === "AskUserQuestion") {
141→        const input = cr.request.input as { questions?: UserQuestion[] };
142→        const questions = Array.isArray(input.questions) ? input.questions : [];
143→        return {
144→          id: nextId(),
145→          role: "system",
146→          content: "Question from Claude",
147→          timestamp: Date.now(),
148→          userQuestion: {
149→            requestId: cr.request_id,
150→            questions,
151→          },
152→        };
153→      }
154→
155→      return {
156→        id: nextId(),
157→        role: "system",
158→        content: `Tool approval requested: ${cr.request.tool_name}`,
159→        timestamp: Date.now(),
160→        controlRequest: {
161→          id: cr.request_id,
162→          tool_name: cr.request.tool_name,
163→          input: cr.request.input,
164→        },
165→      };
166→    }
167→  }
168→
169→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
170→    return {
171→      id: nextId(),
172→      role: "system",
173→      content: `Error: ${relayMsg.error}`,
174→      timestamp: Date.now(),
175→    };
176→  }
177→
178→  return null;
179→}
180→
181→export function useWebSocket() {
182→  const wsRef = useRef<WebSocket | null>(null);
183→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
184→  const [connected, setConnected] = useState(false);
185→
186→  // Multi-agent state
187→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
188→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
189→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
190→
191→  // Task state
192→  const [tasks, setTasks] = useState<Task[]>([]);
193→
194→  // Per-agent deduplication: track count of processed messages per agent
195→  // to avoid duplicating messages already in local state during history replay.
196→  const processedCountRef = useRef<Map<string, number>>(new Map());
197→
198→  /** Immutably update a single agent's state in the Map. */
199→  const updateAgent = useCallback(
200→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
201→      setAgents((prev) => {
202→        const existing = prev.get(agentId);
203→        if (!existing) return prev;
204→        const next = new Map(prev);
205→        next.set(agentId, updater(existing));
206→        return next;
207→      });
208→    },
209→    []
210→  );
211→
212→  const connect = useCallback(() => {
213→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
214→    if (wsRef.current) {
215→      wsRef.current.close();
216→      wsRef.current = null;
217→    }
218→
219→    const ws = new WebSocket(WS_URL);
220→    wsRef.current = ws;
221→
222→    ws.onopen = () => setConnected(true);
223→
224→    ws.onclose = () => {
225→      setConnected(false);
226→      wsRef.current = null;
227→      // Reconnection guard: clear any existing timer before scheduling
228→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
229→      reconnectTimer.current = setTimeout(() => connect(), 2000);
230→    };
231→
232→    ws.onerror = () => {
233→      // onclose will fire after onerror, which triggers reconnect
234→    };
235→
236→    ws.onmessage = (event) => {
237→      let data: ServerMessage;
238→      try {
239→        data = JSON.parse(event.data as string);
240→      } catch {
241→        return;
242→      }
243→
244→      // ── task_list: full task list from server ──
245→      if (data.type === "task_list") {
246→        setTasks((data as ServerTaskList).tasks);
247→        return;
248→      }
249→
250→      // ── task_updated: single task changed ──
251→      if (data.type === "task_updated") {
252→        const updated = (data as ServerTaskUpdated).task;
253→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
254→        return;
255→      }
256→
257→      // ── task_deleted: remove task ──
258→      if (data.type === "task_deleted") {
259→        const deletedId = (data as ServerTaskDeleted).taskId;
260→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
261→        return;
262→      }
263→
264→      // ── message_history: replay full history from server ──
265→      if (data.type === "message_history") {
266→        const historyMsg = data as ServerMessageHistory;
267→        const agentId = historyMsg.agentId;
268→        const serverMessages = historyMsg.messages;
269→
270→        // Convert all server messages to ChatMessages + extract raw Claude messages
271→        const chatMessages: ChatMessage[] = [];
272→        const rawMessages: ClaudeMessage[] = [];
273→        for (const sm of serverMessages) {
274→          if (sm.type === "relay") {
275→            rawMessages.push(sm.message);
276→          }
277→          const cm = relayChatMessage(agentId, sm);
278→          if (cm) chatMessages.push(cm);
279→        }
280→
281→        // Skip messages already processed locally (dedup)
282→        const alreadyProcessed = processedCountRef.current.get(agentId) ?? 0;
283→        const newMessages = chatMessages.slice(alreadyProcessed);
284→
285→        if (newMessages.length > 0) {
286→          setAgents((prev) => {
287→            const existing = prev.get(agentId);
288→            if (!existing) {
289→              // Agent not yet in local state — create it
290→              const next = new Map(prev);
291→              next.set(agentId, {
292→                status: "idle",
293→                messages: chatMessages, // use full history for new agent
294→                rawMessages,
295→                label: "",
296→                tmuxSession: null,
297→                createdAt: 0,
298→              });
299→              return next;
300→            }
301→            // Replace messages with full server history (source of truth)
302→            const next = new Map(prev);
303→            next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
304→            return next;
305→          });
306→        }
307→
308→        processedCountRef.current.set(agentId, chatMessages.length);
309→        return;
310→      }
311→
312→      // ── history_cleared: wipe local messages for this agent ──
313→      if (data.type === "history_cleared") {
314→        updateAgent(data.agentId, (prev) => ({
315→          ...prev,
316→          messages: [],
317→          rawMessages: [],
318→        }));
319→        processedCountRef.current.set(data.agentId, 0);
320→        return;
321→      }
322→
323→      // ── cli_disconnected: show system message ──
324→      if (data.type === "cli_disconnected") {
325→        updateAgent(data.agentId, (prev) => ({
326→          ...prev,
327→          messages: [
328→            ...prev.messages,
329→            {
330→              id: nextId(),
331→              role: "system",
332→              content: "CLI session ended",
333→              timestamp: Date.now(),
334→            },
335→          ],
336→        }));
337→        return;
338→      }
339→
340→      // ── cli_connected: show system message ──
341→      if (data.type === "cli_connected") {
342→        updateAgent(data.agentId, (prev) => ({
343→          ...prev,
344→          messages: [
345→            ...prev.messages,
346→            {
347→              id: nextId(),
348→              role: "system",
349→              content: "CLI reconnected",
350→              timestamp: Date.now(),
351→            },
352→          ],
353→        }));
354→        return;
355→      }
356→
357→      // ── agent_list: reconcile sidebar state from server ──
358→      if (data.type === "agent_list") {
359→        const serverAgents = data.agents as AgentInfo[];
360→        setAgents((prev) => {
361→          const next = new Map(prev);
362→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
363→
364→          // Update or add agents from server
365→          for (const info of serverAgents) {
366→            const existing = next.get(info.agentId);
367→            if (existing) {
368→              next.set(info.agentId, {
369→                ...existing,
370→                status: info.status,
371→                tmuxSession: info.tmuxSession,
372→                label: info.label,
373→              });
374→            } else {
375→              next.set(info.agentId, {
376→                status: info.status,
377→                messages: [],
378→                rawMessages: [],
379→                label: info.label,
380→                tmuxSession: info.tmuxSession,
381→                createdAt: info.createdAt,
382→              });
383→            }
384→          }
385→
386→          // Remove agents no longer on the server
387→          for (const id of next.keys()) {
388→            if (!serverIds.has(id)) {
389→              next.delete(id);
390→            }
391→          }
392→
393→          return next;
394→        });
395→        setAgentOrder(serverAgents.map((a) => a.agentId));
396→        return;
397→      }
398→
399→      // ── spawned: auto-select the newly created agent ──
400→      if (data.type === "spawned") {
401→        setActiveAgentId(data.agentId);
402→        return;
403→      }
404→
405→      // ── status: update a specific agent's status ──
406→      if (data.type === "status") {
407→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
408→        return;
409→      }
410→
411→      // ── error: append to agent's message list ──
412→      if (data.type === "error") {
413→        updateAgent(data.agentId, (prev) => ({
414→          ...prev,
415→          messages: [
416→            ...prev.messages,
