  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Resilience features
 18→ *
 19→ * - **Server-side message history** — every relay message is stored per-agent.
 20→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 21→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 22→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 23→ *   can reconnect to the new server if they retry their WebSocket connection.
 24→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 25→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 26→ *
 27→ * ## Message flow
 28→ *
 29→ * 1. Browser sends `{ type: "spawn", prompt }`.
 30→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 31→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 32→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 33→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 34→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 35→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 36→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 37→ */
 38→import { WebSocketServer, WebSocket } from "ws";
 39→import { execSync, spawn } from "child_process";
 40→import { randomBytes } from "crypto";
 41→import type { IncomingMessage } from "http";
 42→import type {
 43→  BrowserMessage,
 44→  ClaudeMessage,
 45→  ServerMessage,
 46→  AgentStatus,
 47→  AgentInfo,
 48→  Task,
 49→} from "../lib/types";
 50→import { SessionStore, type PersistedAgent } from "./session-store";
 51→import { TaskStore } from "./task-store";
 52→
 53→const PORT = 9900;
 54→const TMUX_SESSION_PREFIX = "thos-agent";
 55→
 56→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 57→function isAllowedIP(ip: string | undefined): boolean {
 58→  if (!ip) return false;
 59→  // Strip IPv6-mapped IPv4 prefix
 60→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 61→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 62→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
 63→  const parts = addr.split(".");
 64→  if (parts.length !== 4) return false;
 65→  const first = parseInt(parts[0], 10);
 66→  const second = parseInt(parts[1], 10);
 67→  return first === 100 && second >= 64 && second <= 127;
 68→}
 69→
 70→const wss = new WebSocketServer({
 71→  port: PORT,
 72→  verifyClient: (info) => {
 73→    const ip = info.req.socket.remoteAddress;
 74→    const allowed = isAllowedIP(ip);
 75→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
 76→    return allowed;
 77→  },
 78→});
 79→const store = new SessionStore();
 80→
 81→// ── Multi-agent state ──────────────────────────────────────────────────────
 82→
 83→interface AgentState {
 84→  agentId: string;
 85→  claudeSocket: WebSocket | null;
 86→  tmuxSession: string | null;
 87→  pendingPrompt: string | null;
 88→  status: AgentStatus;
 89→  label: string;
 90→  createdAt: number;
 91→  /** Captured from system/init, used in subsequent user messages. */
 92→  sessionId: string | null;
 93→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
 94→  pendingControlRequests: Map<string, Record<string, unknown>>;
 95→  /** All messages sent to the browser for this agent (source of truth). */
 96→  messageHistory: ServerMessage[];
 97→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
 98→  pendingMessages: string[];
 99→}
100→
101→const agents = new Map<string, AgentState>();
102→const taskStore = new TaskStore();
103→const tasks = new Map<string, Task>();
104→
105→/** All active browser connections (supports multiple tabs). */
106→const browserSockets = new Set<WebSocket>();
107→
108→/** Generate a short random agent ID. */
109→function newAgentId(): string {
110→  return randomBytes(4).toString("hex");
111→}
112→
113→// ── tmux helpers ───────────────────────────────────────────────────────────
114→
115→/** Return the set of currently alive tmux session names matching the thos prefix. */
116→function listAliveTmuxSessions(): Set<string> {
117→  try {
118→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
119→      encoding: "utf-8",
120→    }).trim();
121→    if (!output) return new Set();
122→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
123→  } catch {
124→    return new Set();
125→  }
126→}
127→
128→// ── Persistence helpers ────────────────────────────────────────────────────
129→
130→/** Build a PersistedAgent snapshot from live state. */
131→function toPersistedAgent(agent: AgentState): PersistedAgent {
132→  return {
133→    id: agent.agentId,
134→    state: {
135→      agentId: agent.agentId,
136→      status: agent.status,
137→      tmuxSession: agent.tmuxSession,
138→      label: agent.label,
139→      createdAt: agent.createdAt,
140→      sessionId: agent.sessionId,
141→    },
142→    messageHistory: agent.messageHistory,
143→  };
144→}
145→
146→/** Persist agent state (debounced — use for streaming events). */
147→function persistAgent(agent: AgentState) {
148→  store.save(toPersistedAgent(agent));
149→}
150→
151→/** Persist agent state immediately (use for critical state changes). */
152→function persistAgentSync(agent: AgentState) {
153→  store.saveSync(toPersistedAgent(agent));
154→}
155→
156→// ── Restore from disk on startup ───────────────────────────────────────────
157→
158→function restoreAgents() {
159→  const persisted = store.loadAll();
160→  const aliveSessions = listAliveTmuxSessions();
161→
162→  for (const p of persisted) {
163→    const agent: AgentState = {
164→      agentId: p.state.agentId,
165→      claudeSocket: null,
166→      tmuxSession: p.state.tmuxSession,
167→      pendingPrompt: null,
168→      status: p.state.status,
169→      label: p.state.label,
170→      createdAt: p.state.createdAt,
171→      sessionId: p.state.sessionId,
172→      pendingControlRequests: new Map(),
173→      messageHistory: p.messageHistory,
174→      pendingMessages: [],
175→    };
176→
177→    // Determine status for agents that were active when the server last ran
178→    if (agent.status !== "done" && agent.status !== "error") {
179→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
180→      if (tmuxAlive) {
181→        // tmux session still alive — CLI may reconnect to this server
182→        agent.status = "disconnected";
183→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
184→      } else {
185→        // tmux session gone — agent is archived
186→        agent.status = "done";
187→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
188→      }
189→    }
190→
191→    agents.set(agent.agentId, agent);
192→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${agent.messageHistory.length} messages)`);
193→  }
194→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
195→}
196→
197→restoreAgents();
198→
199→// ── Task restore + helpers ────────────────────────────────────────────────
200→
201→function restoreTasks() {
202→  const persisted = taskStore.loadAll();
203→  for (const t of persisted) {
204→    tasks.set(t.id, t);
205→  }
206→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
207→}
208→
209→restoreTasks();
210→
211→/** Build the full task list sorted by creation time (newest first). */
212→function buildTaskList(): Task[] {
213→  return Array.from(tasks.values()).sort((a, b) => b.createdAt - a.createdAt);
214→}
215→
216→/** Send the full task list to all browsers. */
217→function broadcastTaskList() {
218→  const payload = JSON.stringify({ type: "task_list", tasks: buildTaskList() });
219→  for (const ws of browserSockets) {
220→    if (ws.readyState === WebSocket.OPEN) {
221→      ws.send(payload);
222→    }
223→  }
224→}
225→
226→/** Persist all tasks to disk (sync). */
227→function persistTasks() {
228→  taskStore.saveSync(Array.from(tasks.values()));
229→}
230→
231→// ── Helpers ────────────────────────────────────────────────────────────────
232→
233→/** Send a JSON message to all connected browsers. */
234→function sendToBrowser(msg: ServerMessage) {
235→  const payload = JSON.stringify(msg);
236→  for (const ws of browserSockets) {
237→    if (ws.readyState === WebSocket.OPEN) {
238→      ws.send(payload);
239→    }
240→  }
241→}
242→
243→/** Build a snapshot of all agents for the sidebar. */
244→function buildAgentList(): AgentInfo[] {
245→  return Array.from(agents.values()).map((a) => ({
246→    agentId: a.agentId,
247→    status: a.status,
248→    tmuxSession: a.tmuxSession,
249→    label: a.label,
250→    createdAt: a.createdAt,
251→  }));
252→}
253→
254→/** Send the full agent list to all browsers. */
255→function broadcastAgentList() {
256→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
257→}
258→
259→/** Update an agent's status, notify browsers, broadcast list, and persist. */
260→function setAgentStatus(agentId: string, status: AgentStatus) {
261→  const agent = agents.get(agentId);
262→  if (!agent) return;
263→  agent.status = status;
264→  sendToBrowser({ type: "status", agentId, status });
265→  broadcastAgentList();
266→  persistAgentSync(agent);
267→}
268→
269→/**
270→ * Record a message in the agent's history and send to all browsers.
271→ * This is used for relay messages so that message history is the source of truth.
272→ */
273→function recordAndSend(agentId: string, msg: ServerMessage) {
274→  const agent = agents.get(agentId);
275→  if (agent) {
276→    agent.messageHistory.push(msg);
277→    persistAgent(agent); // debounced — streaming messages come fast
278→  }
279→  sendToBrowser(msg);
280→}
281→
282→// ── Agent lifecycle ────────────────────────────────────────────────────────
283→
284→/**
285→ * Stop a running agent by killing its tmux session and closing the CLI socket.
286→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
287→ */
288→function stopAgent(agentId: string) {
289→  const agent = agents.get(agentId);
290→  if (!agent) return;
291→
292→  if (agent.tmuxSession) {
293→    try {
294→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
295→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
296→    } catch {
297→      // Session may already be dead
298→    }
299→  }
300→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
301→    agent.claudeSocket.close();
302→  }
303→  agent.claudeSocket = null;
304→  setAgentStatus(agentId, "done");
305→}
306→
307→/**
308→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
309→ */
310→function deleteAgent(agentId: string) {
311→  const agent = agents.get(agentId);
312→  if (!agent) return;
313→
314→  if (agent.tmuxSession) {
315→    try {
316→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
317→    } catch {}
318→  }
319→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
320→    agent.claudeSocket.close();
321→  }
322→  agents.delete(agentId);
323→  store.remove(agentId);
324→  broadcastAgentList();
325→}
326→
327→/**
328→ * Spawn a new Claude CLI process inside a tmux session.
329→ *
330→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
331→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
332→ */
333→function spawnClaude(prompt: string): string {
334→  const agentId = newAgentId();
335→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
336→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
337→
338→  const agent: AgentState = {
339→    agentId,
340→    claudeSocket: null,
341→    tmuxSession: null,
342→    pendingPrompt: prompt,
343→    status: "spawning",
344→    label,
345→    createdAt: Date.now(),
346→    sessionId: null,
347→    pendingControlRequests: new Map(),
348→    messageHistory: [],
349→    pendingMessages: [],
350→  };
351→  agents.set(agentId, agent);
352→
353→  // Notify browsers
354→  sendToBrowser({ type: "spawned", agentId });
355→  broadcastAgentList();
356→  persistAgentSync(agent);
357→
358→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
359→  // tmux new-session runs detached (-d) so spawn() returns immediately.
360→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
361→
362→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
363→    stdio: "ignore",
364→  });
365→
366→  tmux.on("error", (err) => {
367→    console.error("[tmux spawn error]", err);
368→    setAgentStatus(agentId, "error");
369→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
370→  });
371→
372→  tmux.on("exit", (code) => {
373→    if (code !== 0) {
374→      console.error(`[tmux] new-session exited with code ${code}`);
375→      setAgentStatus(agentId, "error");
376→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
377→      return;
378→    }
379→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
380→    agent.tmuxSession = sessionName;
381→    broadcastAgentList();
382→    persistAgentSync(agent);
383→  });
384→
385→  return agentId;
386→}
387→
388→// ── Message handlers ───────────────────────────────────────────────────────
389→
390→/**
391→ * Process an incoming NDJSON message from a specific Claude CLI.
392→ *
393→ * Status flow matches the Companion protocol:
394→ * - hook_response → send pending prompt → "thinking"
395→ * - system/init   → "connected" + capture session_id
396→ * - assistant      → "thinking"
397→ * - result         → "connected" (CLI stays alive for multi-turn)
398→ * - CLI disconnect → "done" (handled in connection close handler)
399→ */
400→function handleClaudeMessage(agentId: string, raw: string) {
401→  const agent = agents.get(agentId);
402→  if (!agent) return;
403→
404→  let msg: ClaudeMessage;
405→  try {
406→    msg = JSON.parse(raw);
407→  } catch {
408→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
409→    return;
410→  }
411→
412→  // Silently ignore keep_alive messages
413→  if (msg.type === "keep_alive") return;
414→
415→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
416→
417→  // After hook_response, send the pending prompt
418→  if (
419→    msg.type === "system" &&
420→    (msg as { subtype?: string }).subtype === "hook_response" &&
421→    agent.pendingPrompt &&
422→    agent.claudeSocket?.readyState === WebSocket.OPEN
423→  ) {
424→    const userMsg = JSON.stringify({
425→      type: "user",
426→      message: { role: "user", content: agent.pendingPrompt },
427→      parent_tool_use_id: null,
428→      session_id: agent.sessionId ?? "",
429→    });
430→    console.log(`[server → claude:${agentId}]`, userMsg);
431→    agent.claudeSocket.send(userMsg + "\n");
432→    agent.pendingPrompt = null;
433→    setAgentStatus(agentId, "thinking");
434→  }
435→
436→  // Track status based on message type
437→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
438→    // Capture session_id for subsequent user messages
439→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
440→    setAgentStatus(agentId, "connected");
441→  } else if (msg.type === "assistant") {
442→    setAgentStatus(agentId, "thinking");
443→  } else if (msg.type === "result") {
444→    // CLI stays alive after result — ready for the next turn.
445→    // Status only goes to "done" when the CLI WebSocket actually closes.
446→    setAgentStatus(agentId, "connected");
447→  }
448→
449→  // Store control_request inputs for building proper responses later
450→  if (msg.type === "control_request") {
451→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
452→    if (cr.request_id && cr.request?.input) {
453→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
454→    }
455→  }
456→
457→  // Record in history and relay to browsers
458→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
459→}
460→
461→/**
462→ * Process an incoming JSON message from the browser.
463→ * - `spawn`: create a new agent (does NOT kill others).
464→ * - `send_message`: forward a follow-up user message to the specified agent.
465→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
466→ * - `kill_agent`: stop the CLI and tmux session.
467→ * - `delete_agent`: permanently remove an agent.
468→ * - `rename_agent`: update an agent's label.
469→ * - `clear_history`: wipe an agent's message history.
470→ */
471→function handleBrowserMessage(raw: string) {
472→  let msg: BrowserMessage;
473→  try {
474→    msg = JSON.parse(raw);
475→  } catch {
476→    console.error("[browser] invalid JSON:", raw);
477→    return;
478→  }
479→
480→  console.log("[browser →]", msg.type);
481→
482→  switch (msg.type) {
483→    case "spawn":
484→      spawnClaude(msg.prompt);
485→      break;
486→
487→    case "send_message": {
488→      const agent = agents.get(msg.agentId);
489→      if (!agent) {
490→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
491→        break;
492→      }
493→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
494→        const userMsg = JSON.stringify({
495→          type: "user",
496→          message: { role: "user", content: msg.content },
497→          parent_tool_use_id: null,
498→          session_id: agent.sessionId ?? "",
499→        });
500→        agent.claudeSocket.send(userMsg + "\n");
501→        setAgentStatus(msg.agentId, "thinking");
502→      } else {
503→        // Queue message for delivery when CLI reconnects
504→        const userMsg = JSON.stringify({
505→          type: "user",
506→          message: { role: "user", content: msg.content },
507→          parent_tool_use_id: null,
508→          session_id: agent.sessionId ?? "",
509→        });
510→        agent.pendingMessages.push(userMsg);
511→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
512→        persistAgentSync(agent);
513→      }
514→      break;
515→    }
516→
517→    case "control_response": {
518→      const agent = agents.get(msg.agentId);
519→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
520→        // Retrieve the original tool input to include as updatedInput (required by protocol)
521→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
522→        agent.pendingControlRequests.delete(msg.request_id);
523→
524→        // If the browser sent answers (from AskUserQuestion), merge them into the input
525→        const answers = (msg as { answers?: Record<string, string> }).answers;
526→        const updatedInput = answers
527→          ? { ...originalInput, answers }
528→          : originalInput;
529→
530→        const response = JSON.stringify({
531→          type: "control_response",
532→          response: {
533→            subtype: "success",
534→            request_id: msg.request_id,
535→            response: msg.allow
536→              ? { behavior: "allow", updatedInput }
537→              : { behavior: "deny", message: "Denied by user" },
538→          },
539→        });
540→        agent.claudeSocket.send(response + "\n");
541→      }
542→      break;
543→    }
544→
545→    case "kill_agent":
546→      stopAgent(msg.agentId);
547→      break;
548→
549→    case "delete_agent":
550→      deleteAgent(msg.agentId);
551→      break;
552→
553→    case "rename_agent": {
554→      const agent = agents.get(msg.agentId);
555→      if (!agent) break;
556→      agent.label = msg.label;
557→      broadcastAgentList();
558→      persistAgentSync(agent);
559→      break;
560→    }
561→
562→    case "clear_history": {
563→      const agent = agents.get(msg.agentId);
564→      if (!agent) break;
565→      agent.messageHistory = [];
566→      persistAgentSync(agent);
567→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
568→      break;
569→    }
570→
571→    case "create_task": {
572→      const taskId = randomBytes(4).toString("hex");
573→      const task: Task = {
574→        id: taskId,
575→        title: msg.title,
576→        description: msg.description,
577→        status: "todo",
578→        priority: msg.priority,
579→        agentId: null,
580→        createdAt: Date.now(),
581→        updatedAt: Date.now(),
582→      };
583→      tasks.set(taskId, task);
584→      persistTasks();
585→      broadcastTaskList();
586→      break;
587→    }
588→
589→    case "update_task": {
590→      const task = tasks.get(msg.taskId);
591→      if (!task) break;
592→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
593→      persistTasks();
594→      broadcastTaskList();
595→      break;
596→    }
597→
598→    case "delete_task": {
599→      tasks.delete(msg.taskId);
600→      persistTasks();
601→      broadcastTaskList();
602→      break;
603→    }
604→
605→    case "delegate_task": {
606→      const task = tasks.get(msg.taskId);
607→      if (!task) break;
608→      const prompt = `Task: ${task.title}\n\n${task.description}`;
609→      const agentId = spawnClaude(prompt);
610→      task.agentId = agentId;
611→      task.status = "in-progress";
612→      task.updatedAt = Date.now();
613→      persistTasks();
614→      broadcastTaskList();
615→      break;
616→    }
617→  }
618→}
619→
620→// ── Send message history to a single browser socket ────────────────────────
621→
622→/** Send full state to a newly connected browser: agent list + message history per agent. */
623→function sendFullStateToSocket(ws: WebSocket) {
624→  if (ws.readyState !== WebSocket.OPEN) return;
