  | BrowserSpawn
  | BrowserSendMessage
  | BrowserControlResponse
  | BrowserKillAgent
  | BrowserDeleteAgent
  | BrowserRenameAgent
  | BrowserClearHistory
  | BrowserCreateTask
  | BrowserUpdateTask
  | BrowserDeleteTask
  | BrowserDelegateTask;

