  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * Resilience features:
 11→ * - Handles `message_history` replay from server on connect/reconnect.
 12→ * - Handles `cli_disconnected` / `cli_connected` events.
 13→ * - Deduplicates messages using a per-agent Set of seen message IDs.
 14→ * - Robust reconnection guard (clears previous timer before scheduling).
 15→ */
 16→
 17→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 18→import type {
 19→  AgentInfo,
 20→  AgentStatus,
 21→  ChatMessage,
 22→  ClaudeAssistant,
 23→  ClaudeControlRequest,
 24→  ClaudeMessage,
 25→  ClaudeResult,
 26→  ClaudeSystemInit,
 27→  ServerFullState,
 28→  ServerMessage,
 29→  ServerMessageHistory,
 30→  ServerTaskList,
 31→  ServerTaskUpdated,
 32→  ServerTaskDeleted,
 33→  Task,
 34→  TaskPriority,
 35→  ToolCallInfo,
 36→  UserQuestion,
 37→} from "@/lib/types";
 38→
 39→/** Connect to the WS server on the same host the page was loaded from. */
 40→const WS_URL =
 41→  typeof window !== "undefined"
 42→    ? `ws://${window.location.hostname}:9900/browser`
 43→    : "ws://localhost:9900/browser";
 44→
 45→/** Per-agent client state. */
 46→export interface AgentClientState {
 47→  status: AgentStatus;
 48→  messages: ChatMessage[];
 49→  /** Raw Claude NDJSON messages for debug view. */
 50→  rawMessages: ClaudeMessage[];
 51→  label: string;
 52→  tmuxSession: string | null;
 53→  createdAt: number;
 54→}
 55→
 56→/**
 57→ * Extract displayable text from a Claude assistant message.
 58→ * Content blocks may be text, tool_use, or tool_result — each is
 59→ * handled defensively since the array structure can vary.
 60→ */
 61→function extractText(msg: ClaudeAssistant): string {
 62→  const blocks = msg.message?.content;
 63→  if (!blocks || !Array.isArray(blocks)) return "";
 64→  return blocks
 65→    .map((b) => {
 66→      if (b.type === "text") return b.text;
 67→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 68→      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
 69→      return "";
 70→    })
 71→    .filter(Boolean)
 72→    .join("\n");
 73→}
 74→
 75→/** Module-level counter for generating unique message IDs. */
 76→let msgCounter = 0;
 77→function nextId() {
 78→  return `msg-${Date.now()}-${++msgCounter}`;
 79→}
 80→
 81→/**
 82→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 83→ * Used both for live messages and for replaying message_history.
 84→ */
 85→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
 86→  if (relayMsg.type === "relay") {
 87→    const msg = relayMsg.message;
 88→
 89→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 90→      const init = msg as ClaudeSystemInit;
 91→      return {
 92→        id: nextId(),
 93→        role: "system",
 94→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
 95→        timestamp: Date.now(),
 96→      };
 97→    }
 98→
 99→    if (msg.type === "assistant") {
100→      const assistant = msg as ClaudeAssistant;
101→      const text = extractText(assistant);
102→      if (!text) return null;
103→
104→      const blocks = assistant.message?.content ?? [];
105→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
106→      const toolCalls: ToolCallInfo[] = blocks
107→        .filter((b) => b.type === "tool_use")
108→        .map((b) => ({
109→          name: (b as { name: string }).name,
110→          toolUseId: (b as { id: string }).id,
111→        }));
112→      const isToolOnly = !hasText && toolCalls.length > 0;
113→
114→      return {
115→        id: nextId(),
116→        role: "assistant",
117→        content: text,
118→        timestamp: Date.now(),
119→        toolCalls,
120→        isToolOnly,
121→      };
122→    }
123→
124→    if (msg.type === "result") {
125→      const result = msg as ClaudeResult;
126→      const summary = result.is_error
127→        ? `Error: ${result.error}`
128→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
129→      return {
130→        id: nextId(),
131→        role: "system",
132→        content: summary,
133→        timestamp: Date.now(),
134→      };
135→    }
136→
137→    if (msg.type === "control_request") {
138→      const cr = msg as ClaudeControlRequest;
139→
140→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
141→      if (cr.request.tool_name === "AskUserQuestion") {
142→        const input = cr.request.input as { questions?: UserQuestion[] };
143→        const questions = Array.isArray(input.questions) ? input.questions : [];
144→        return {
145→          id: nextId(),
146→          role: "system",
147→          content: "Question from Claude",
148→          timestamp: Date.now(),
149→          userQuestion: {
150→            requestId: cr.request_id,
151→            questions,
152→          },
153→        };
154→      }
155→
156→      return {
157→        id: nextId(),
158→        role: "system",
159→        content: `Tool approval requested: ${cr.request.tool_name}`,
160→        timestamp: Date.now(),
161→        controlRequest: {
162→          id: cr.request_id,
163→          tool_name: cr.request.tool_name,
164→          input: cr.request.input,
165→        },
166→      };
167→    }
168→  }
169→
170→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
171→    return {
172→      id: nextId(),
173→      role: "system",
174→      content: `Error: ${relayMsg.error}`,
175→      timestamp: Date.now(),
176→    };
177→  }
178→
179→  return null;
180→}
181→
182→export function useWebSocket() {
183→  const wsRef = useRef<WebSocket | null>(null);
184→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
185→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
186→  const closingRef = useRef(false);
187→  const [connected, setConnected] = useState(false);
188→
189→  // Multi-agent state
190→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
191→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
192→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
193→
194→  // Task state
195→  const [tasks, setTasks] = useState<Task[]>([]);
196→
197→  // Per-agent deduplication: track count of processed messages per agent
198→  // to avoid duplicating messages already in local state during history replay.
199→  const processedCountRef = useRef<Map<string, number>>(new Map());
200→
201→  /** Immutably update a single agent's state in the Map. */
202→  const updateAgent = useCallback(
203→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
204→      setAgents((prev) => {
205→        const existing = prev.get(agentId);
206→        if (!existing) return prev;
207→        const next = new Map(prev);
208→        next.set(agentId, updater(existing));
209→        return next;
210→      });
211→    },
212→    []
213→  );
214→
215→  const connect = useCallback(() => {
216→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
217→    if (wsRef.current) {
218→      wsRef.current.close();
219→      wsRef.current = null;
220→    }
221→
222→    // Reset dedup counts on new connection — server will send fresh history
223→    processedCountRef.current.clear();
224→
225→    const ws = new WebSocket(WS_URL);
226→    wsRef.current = ws;
227→
228→    ws.onopen = () => setConnected(true);
229→
230→    ws.onclose = () => {
231→      setConnected(false);
232→      wsRef.current = null;
233→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
234→      if (closingRef.current) return;
235→      // Reconnection guard: clear any existing timer before scheduling
236→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
237→      reconnectTimer.current = setTimeout(() => connect(), 2000);
238→    };
239→
240→    ws.onerror = () => {
241→      // onclose will fire after onerror, which triggers reconnect
242→    };
243→
244→    ws.onmessage = (event) => {
245→      let data: ServerMessage;
246→      try {
247→        data = JSON.parse(event.data as string);
248→      } catch {
249→        return;
250→      }
251→
252→      // ── task_list: full task list from server ──
253→      if (data.type === "task_list") {
254→        setTasks((data as ServerTaskList).tasks);
255→        return;
256→      }
257→
258→      // ── task_updated: single task changed ──
259→      if (data.type === "task_updated") {
260→        const updated = (data as ServerTaskUpdated).task;
261→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
262→        return;
263→      }
264→
265→      // ── task_deleted: remove task ──
266→      if (data.type === "task_deleted") {
267→        const deletedId = (data as ServerTaskDeleted).taskId;
268→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
269→        return;
270→      }
271→
272→      // ── message_history: replay full history from server ──
273→      if (data.type === "message_history") {
274→        const historyMsg = data as ServerMessageHistory;
275→        const agentId = historyMsg.agentId;
276→        const serverMessages = historyMsg.messages;
277→
278→        // Convert all server messages to ChatMessages + extract raw Claude messages
279→        const chatMessages: ChatMessage[] = [];
280→        const rawMessages: ClaudeMessage[] = [];
281→        for (const sm of serverMessages) {
282→          if (sm.type === "relay") {
283→            rawMessages.push(sm.message);
284→          }
285→          const cm = relayChatMessage(agentId, sm);
286→          if (cm) chatMessages.push(cm);
287→        }
288→
289→        // Always replace local messages with server history (source of truth).
290→        // For active agents, live relay messages may have arrived before this
291→        // history replay — the replace ensures we don't lose or duplicate them.
292→        setAgents((prev) => {
293→          const existing = prev.get(agentId);
294→          if (!existing) {
295→            const next = new Map(prev);
296→            next.set(agentId, {
297→              status: "idle",
298→              messages: chatMessages,
299→              rawMessages,
300→              label: "",
301→              tmuxSession: null,
302→              createdAt: 0,
303→            });
304→            return next;
305→          }
306→          const next = new Map(prev);
307→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
308→          return next;
309→        });
310→
311→        processedCountRef.current.set(agentId, chatMessages.length);
312→        return;
313→      }
314→
315→      // ── history_cleared: wipe local messages for this agent ──
316→      if (data.type === "history_cleared") {
317→        updateAgent(data.agentId, (prev) => ({
318→          ...prev,
319→          messages: [],
320→          rawMessages: [],
321→        }));
322→        processedCountRef.current.set(data.agentId, 0);
323→        return;
324→      }
325→
326→      // ── cli_disconnected: show system message ──
327→      if (data.type === "cli_disconnected") {
328→        updateAgent(data.agentId, (prev) => ({
329→          ...prev,
330→          messages: [
331→            ...prev.messages,
332→            {
333→              id: nextId(),
334→              role: "system",
335→              content: "CLI session ended",
336→              timestamp: Date.now(),
337→            },
338→          ],
339→        }));
340→        return;
341→      }
342→
343→      // ── cli_connected: show system message ──
344→      if (data.type === "cli_connected") {
345→        updateAgent(data.agentId, (prev) => ({
346→          ...prev,
347→          messages: [
348→            ...prev.messages,
349→            {
350→              id: nextId(),
351→              role: "system",
352→              content: "CLI reconnected",
353→              timestamp: Date.now(),
354→            },
355→          ],
356→        }));
357→        return;
358→      }
359→
360→      // ── agent_list: reconcile sidebar state from server ──
361→      if (data.type === "agent_list") {
362→        const serverAgents = data.agents as AgentInfo[];
363→        setAgents((prev) => {
364→          const next = new Map(prev);
365→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
366→
367→          // Update or add agents from server
368→          for (const info of serverAgents) {
369→            const existing = next.get(info.agentId);
370→            if (existing) {
371→              next.set(info.agentId, {
372→                ...existing,
373→                status: info.status,
374→                tmuxSession: info.tmuxSession,
375→                label: info.label,
376→              });
377→            } else {
378→              next.set(info.agentId, {
379→                status: info.status,
380→                messages: [],
381→                rawMessages: [],
382→                label: info.label,
383→                tmuxSession: info.tmuxSession,
384→                createdAt: info.createdAt,
385→              });
386→            }
387→          }
388→
389→          // Remove agents no longer on the server
390→          for (const id of next.keys()) {
391→            if (!serverIds.has(id)) {
392→              next.delete(id);
393→            }
394→          }
395→
396→          return next;
397→        });
398→        setAgentOrder(serverAgents.map((a) => a.agentId));
399→
400→        // Auto-select the first agent on initial load when nothing is selected
401→        setActiveAgentId((prev) => {
402→          if (prev !== null) return prev;
403→          if (serverAgents.length === 0) return null;
404→          return serverAgents[0].agentId;
405→        });
406→        return;
407→      }
408→
409→      // ── spawned: auto-select the newly created agent ──
410→      if (data.type === "spawned") {
411→        setActiveAgentId(data.agentId);
412→        return;
413→      }
414→
415→      // ── status: update a specific agent's status ──
416→      if (data.type === "status") {
417→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
418→        return;
419→      }
420→
421→      // ── error: append to agent's message list ──
422→      if (data.type === "error") {
423→        updateAgent(data.agentId, (prev) => ({
424→          ...prev,
425→          messages: [
426→            ...prev.messages,
427→            {
428→              id: nextId(),
429→              role: "system",
430→              content: `Error: ${data.error}`,
431→              timestamp: Date.now(),
432→            },
433→          ],
434→        }));
435→        // Track processed count for dedup
436→        processedCountRef.current.set(
437→          data.agentId,
438→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
439→        );
440→        return;
441→      }
442→
443→      // ── relay: append claude message to agent's history ──
444→      if (data.type === "relay") {
445→        const agentId = data.agentId;
446→        const rawMsg = data.message;
447→        const chatMsg = relayChatMessage(agentId, data);
448→
449→        updateAgent(agentId, (prev) => ({
450→          ...prev,
451→          rawMessages: [...prev.rawMessages, rawMsg],
452→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
453→        }));
454→        if (chatMsg) {
455→          // Track processed count for dedup
456→          processedCountRef.current.set(
457→            agentId,
458→            (processedCountRef.current.get(agentId) ?? 0) + 1
459→          );
460→        }
461→        return;
462→      }
463→    };
464→  }, [updateAgent]);
465→
466→  useEffect(() => {
467→    closingRef.current = false;
468→    connect();
469→    return () => {
470→      closingRef.current = true;
471→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
472→      wsRef.current?.close();
473→    };
474→  }, [connect]);
475→
476→  const send = useCallback((data: object) => {
477→    if (wsRef.current?.readyState === WebSocket.OPEN) {
478→      wsRef.current.send(JSON.stringify(data));
479→    }
480→  }, []);
481→
482→  const spawnAgent = useCallback(
483→    (prompt: string) => {
484→      send({ type: "spawn", prompt });
485→    },
486→    [send]
487→  );
488→
489→  const sendMessage = useCallback(
490→    (content: string) => {
491→      if (!activeAgentId) return;
492→      // Optimistically add user message to local state
493→      updateAgent(activeAgentId, (prev) => ({
494→        ...prev,
495→        messages: [
496→          ...prev.messages,
497→          {
498→            id: nextId(),
499→            role: "user",
500→            content,
501→            timestamp: Date.now(),
502→          },
503→        ],
504→      }));
505→      send({ type: "send_message", agentId: activeAgentId, content });
506→    },
507→    [send, activeAgentId, updateAgent]
508→  );
509→
510→  const respondToControl = useCallback(
511→    (requestId: string, allow: boolean) => {
512→      if (!activeAgentId) return;
513→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
514→      updateAgent(activeAgentId, (prev) => ({
515→        ...prev,
516→        messages: prev.messages.map((m) =>
517→          m.controlRequest?.id === requestId
518→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
519→            : m
520→        ),
521→      }));
522→    },
523→    [send, activeAgentId, updateAgent]
524→  );
525→
526→  /** Respond to an AskUserQuestion control request with the user's selections. */
527→  const respondToUserQuestion = useCallback(
528→    (requestId: string, answers: Record<string, string>) => {
529→      if (!activeAgentId) return;
530→      send({
531→        type: "control_response",
532→        agentId: activeAgentId,
533→        request_id: requestId,
534→        allow: true,
535→        answers,
536→      });
537→      updateAgent(activeAgentId, (prev) => ({
538→        ...prev,
539→        messages: prev.messages.map((m) =>
540→          m.userQuestion?.requestId === requestId
541→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
542→            : m
543→        ),
544→      }));
545→    },
546→    [send, activeAgentId, updateAgent]
547→  );
548→
549→  // ── Agent management actions ──────────────────────────────────────────────
550→
551→  const killAgent = useCallback(
552→    (agentId: string) => {
553→      send({ type: "kill_agent", agentId });
554→    },
555→    [send]
556→  );
557→
558→  const deleteAgent = useCallback(
559→    (agentId: string) => {
560→      send({ type: "delete_agent", agentId });
561→      // Deselect if we just deleted the active agent
562→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
563→    },
564→    [send]
565→  );
566→
567→  const renameAgent = useCallback(
568→    (agentId: string, label: string) => {
569→      send({ type: "rename_agent", agentId, label });
570→    },
571→    [send]
572→  );
573→
574→  const clearHistory = useCallback(
575→    (agentId: string) => {
576→      send({ type: "clear_history", agentId });
577→    },
578→    [send]
579→  );
580→
581→  // ── Task actions ──────────────────────────────────────────────────────────
582→
583→  const createTask = useCallback(
584→    (title: string, description: string, priority: TaskPriority) => {
585→      send({ type: "create_task", title, description, priority });
586→    },
587→    [send]
588→  );
589→
590→  const updateTask = useCallback(
591→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
592→      send({ type: "update_task", taskId, updates });
593→    },
594→    [send]
595→  );
596→
597→  const deleteTask = useCallback(
598→    (taskId: string) => {
599→      send({ type: "delete_task", taskId });
600→    },
601→    [send]
602→  );
603→
604→  const delegateTask = useCallback(
605→    (taskId: string) => {
606→      send({ type: "delegate_task", taskId });
607→    },
608→    [send]
609→  );
610→
611→  // Derived values for the active agent
612→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
613→  const activeStatus = useMemo<AgentStatus>(
614→    () => activeAgent?.status ?? "idle",
615→    [activeAgent?.status]
616→  );
617→  const activeMessages = useMemo<ChatMessage[]>(
618→    () => activeAgent?.messages ?? [],
619→    [activeAgent?.messages]
620→  );
621→  const activeRawMessages = useMemo<ClaudeMessage[]>(
622→    () => activeAgent?.rawMessages ?? [],
623→    [activeAgent?.rawMessages]
624→  );
625→
626→  return {
627→    connected,
628→    agents,
629→    agentOrder,
630→    activeAgentId,
631→    setActiveAgentId,
632→    activeStatus,
633→    activeMessages,
634→    activeRawMessages,
635→    spawnAgent,
636→    sendMessage,
637→    respondToControl,
638→    respondToUserQuestion,
639→    killAgent,
640→    deleteAgent,
641→    renameAgent,
642→    clearHistory,
643→    tasks,
644→    createTask,
645→    updateTask,
646→    deleteTask,
647→    delegateTask,
648→  };
649→}
