361→    questions: UserQuestion[];
362→    resolved?: boolean;
363→  };
364→  /** Tool calls found in this assistant message. */
365→  toolCalls?: ToolCallInfo[];
366→  /** True when this message has only tool_use/tool_result blocks and no text. */
367→  isToolOnly?: boolean;
368→}
