371→
372→export type TaskStatus = "todo" | "in-progress" | "done";
373→export type TaskPriority = "low" | "medium" | "high" | "urgent";
374→
375→/** A user-created task, optionally linked to a Claude agent. */
376→export interface Task {
377→  id: string;
378→  title: string;
379→  description: string;
380→  status: TaskStatus;
381→  priority: TaskPriority;
382→  /** If delegated, the agentId of the spawned Claude agent. */
383→  agentId: string | null;
384→  createdAt: number;
385→  updatedAt: number;
386→}
