ws.onmessage = (event) => {
  let data: ServerMessage;
  try {
    data = JSON.parse(event.data as string);
  } catch {
    return;
  }

  // ── full_state: atomic initial state from server (agents + histories + tasks) ──
  if (data.type === "full_state") {
    const fullState = data as ServerFullState;

    // Build a lookup of histories keyed by agentId for O(1) access
    const historyMap = new Map<string, { chat: ChatMessage[]; raw: ClaudeMessage[] }>();
    for (const h of fullState.histories) {
      const chatMessages: ChatMessage[] = [];
      const rawMessages: ClaudeMessage[] = [];
      for (const sm of h.messages) {
        if (sm.type === "relay") {
          rawMessages.push(sm.message);
        }
        const cm = relayChatMessage(h.agentId, sm);
        if (cm) chatMessages.push(cm);
      }
      historyMap.set(h.agentId, { chat: chatMessages, raw: rawMessages });
    }

    // Build the complete agents Map in one shot — agents already have their messages
    const newAgents = new Map<string, AgentClientState>();
    for (const info of fullState.agents) {
      const history = historyMap.get(info.agentId);
      newAgents.set(info.agentId, {
        status: info.status,
        messages: history?.chat ?? [],
        rawMessages: history?.raw ?? [],
        label: info.label,
        tmuxSession: info.tmuxSession,
        createdAt: info.createdAt,
      });
      processedCountRef.current.set(info.agentId, history?.chat.length ?? 0);
    }

    setAgents(newAgents);
    setAgentOrder(fullState.agents.map((a) => a.agentId));
    setTasks(fullState.tasks);

    // Auto-select the first agent if nothing is selected
    setActiveAgentId((prev) => {
      if (prev !== null) return prev;
      if (fullState.agents.length === 0) return null;
      return fullState.agents[0].agentId;
    });
    return;
  }

  // ── task_list: full task list from server ──
  if (data.type === "task_list") {
    setTasks((data as ServerTaskList).tasks);
    return;
  }

