  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * Resilience features:
 11→ * - Handles `message_history` replay from server on connect/reconnect.
 12→ * - Handles `cli_disconnected` / `cli_connected` events.
 13→ * - Deduplicates messages using a per-agent Set of seen message IDs.
 14→ * - Robust reconnection guard (clears previous timer before scheduling).
 15→ */
 16→
 17→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 18→import type {
 19→  AgentInfo,
 20→  AgentStatus,
 21→  ChatMessage,
 22→  ClaudeAssistant,
 23→  ClaudeControlRequest,
 24→  ClaudeMessage,
 25→  ClaudeResult,
 26→  ClaudeSystemInit,
 27→  ServerMessage,
 28→  ServerMessageHistory,
 29→  ServerTaskList,
 30→  ServerTaskUpdated,
 31→  ServerTaskDeleted,
 32→  Task,
 33→  TaskPriority,
 34→  ToolCallInfo,
 35→  UserQuestion,
 36→} from "@/lib/types";
 37→
 38→/** Connect to the WS server on the same host the page was loaded from. */
 39→const WS_URL =
 40→  typeof window !== "undefined"
 41→    ? `ws://${window.location.hostname}:9900/browser`
 42→    : "ws://localhost:9900/browser";
 43→
 44→/** Per-agent client state. */
 45→export interface AgentClientState {
 46→  status: AgentStatus;
 47→  messages: ChatMessage[];
 48→  /** Raw Claude NDJSON messages for debug view. */
 49→  rawMessages: ClaudeMessage[];
 50→  label: string;
 51→  tmuxSession: string | null;
 52→  createdAt: number;
 53→}
 54→
 55→/**
 56→ * Extract displayable text from a Claude assistant message.
 57→ * Content blocks may be text, tool_use, or tool_result — each is
 58→ * handled defensively since the array structure can vary.
 59→ */
 60→function extractText(msg: ClaudeAssistant): string {
 61→  const blocks = msg.message?.content;
 62→  if (!blocks || !Array.isArray(blocks)) return "";
 63→  return blocks
 64→    .map((b) => {
 65→      if (b.type === "text") return b.text;
 66→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 67→      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
 68→      return "";
 69→    })
 70→    .filter(Boolean)
 71→    .join("\n");
 72→}
 73→
 74→/** Module-level counter for generating unique message IDs. */
 75→let msgCounter = 0;
 76→function nextId() {
 77→  return `msg-${Date.now()}-${++msgCounter}`;
 78→}
 79→
 80→/**
 81→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 82→ * Used both for live messages and for replaying message_history.
 83→ */
 84→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
 85→  if (relayMsg.type === "relay") {
 86→    const msg = relayMsg.message;
 87→
 88→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 89→      const init = msg as ClaudeSystemInit;
 90→      return {
 91→        id: nextId(),
 92→        role: "system",
 93→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
 94→        timestamp: Date.now(),
 95→      };
 96→    }
 97→
 98→    if (msg.type === "assistant") {
 99→      const assistant = msg as ClaudeAssistant;
100→      const text = extractText(assistant);
101→      if (!text) return null;
102→
103→      const blocks = assistant.message?.content ?? [];
104→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
105→      const toolCalls: ToolCallInfo[] = blocks
106→        .filter((b) => b.type === "tool_use")
107→        .map((b) => ({
108→          name: (b as { name: string }).name,
109→          toolUseId: (b as { id: string }).id,
110→        }));
111→      const isToolOnly = !hasText && toolCalls.length > 0;
112→
113→      return {
114→        id: nextId(),
115→        role: "assistant",
116→        content: text,
117→        timestamp: Date.now(),
118→        toolCalls,
119→        isToolOnly,
120→      };
121→    }
122→
123→    if (msg.type === "result") {
124→      const result = msg as ClaudeResult;
125→      const summary = result.is_error
126→        ? `Error: ${result.error}`
127→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
128→      return {
129→        id: nextId(),
130→        role: "system",
131→        content: summary,
132→        timestamp: Date.now(),
133→      };
134→    }
135→
136→    if (msg.type === "control_request") {
137→      const cr = msg as ClaudeControlRequest;
138→
139→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
140→      if (cr.request.tool_name === "AskUserQuestion") {
141→        const input = cr.request.input as { questions?: UserQuestion[] };
142→        const questions = Array.isArray(input.questions) ? input.questions : [];
143→        return {
144→          id: nextId(),
145→          role: "system",
146→          content: "Question from Claude",
147→          timestamp: Date.now(),
148→          userQuestion: {
149→            requestId: cr.request_id,
150→            questions,
151→          },
152→        };
153→      }
154→
155→      return {
156→        id: nextId(),
157→        role: "system",
158→        content: `Tool approval requested: ${cr.request.tool_name}`,
159→        timestamp: Date.now(),
160→        controlRequest: {
161→          id: cr.request_id,
162→          tool_name: cr.request.tool_name,
163→          input: cr.request.input,
164→        },
165→      };
166→    }
167→  }
168→
169→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
170→    return {
171→      id: nextId(),
172→      role: "system",
173→      content: `Error: ${relayMsg.error}`,
174→      timestamp: Date.now(),
175→    };
176→  }
177→
178→  return null;
179→}
180→
181→export function useWebSocket() {
182→  const wsRef = useRef<WebSocket | null>(null);
183→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
184→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
185→  const closingRef = useRef(false);
186→  const [connected, setConnected] = useState(false);
187→
188→  // Multi-agent state
189→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
190→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
191→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
192→
193→  // Task state
194→  const [tasks, setTasks] = useState<Task[]>([]);
195→
196→  // Per-agent deduplication: track count of processed messages per agent
197→  // to avoid duplicating messages already in local state during history replay.
198→  const processedCountRef = useRef<Map<string, number>>(new Map());
199→
200→  /** Immutably update a single agent's state in the Map. */
201→  const updateAgent = useCallback(
202→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
203→      setAgents((prev) => {
204→        const existing = prev.get(agentId);
205→        if (!existing) return prev;
206→        const next = new Map(prev);
207→        next.set(agentId, updater(existing));
208→        return next;
209→      });
210→    },
211→    []
212→  );
213→
214→  const connect = useCallback(() => {
215→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
216→    if (wsRef.current) {
217→      wsRef.current.close();
218→      wsRef.current = null;
219→    }
220→
221→    // Reset dedup counts on new connection — server will send fresh history
222→    processedCountRef.current.clear();
223→
224→    const ws = new WebSocket(WS_URL);
225→    wsRef.current = ws;
226→
227→    ws.onopen = () => setConnected(true);
228→
229→    ws.onclose = () => {
230→      setConnected(false);
231→      wsRef.current = null;
232→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
233→      if (closingRef.current) return;
234→      // Reconnection guard: clear any existing timer before scheduling
235→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
236→      reconnectTimer.current = setTimeout(() => connect(), 2000);
237→    };
238→
239→    ws.onerror = () => {
240→      // onclose will fire after onerror, which triggers reconnect
241→    };
242→
243→    ws.onmessage = (event) => {
244→      let data: ServerMessage;
245→      try {
246→        data = JSON.parse(event.data as string);
247→      } catch {
248→        return;
249→      }
250→
251→      // ── task_list: full task list from server ──
252→      if (data.type === "task_list") {
253→        setTasks((data as ServerTaskList).tasks);
254→        return;
255→      }
256→
257→      // ── task_updated: single task changed ──
258→      if (data.type === "task_updated") {
259→        const updated = (data as ServerTaskUpdated).task;
260→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
261→        return;
262→      }
263→
264→      // ── task_deleted: remove task ──
265→      if (data.type === "task_deleted") {
266→        const deletedId = (data as ServerTaskDeleted).taskId;
267→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
268→        return;
269→      }
270→
271→      // ── message_history: replay full history from server ──
272→      if (data.type === "message_history") {
273→        const historyMsg = data as ServerMessageHistory;
274→        const agentId = historyMsg.agentId;
275→        const serverMessages = historyMsg.messages;
276→
277→        // Convert all server messages to ChatMessages + extract raw Claude messages
278→        const chatMessages: ChatMessage[] = [];
279→        const rawMessages: ClaudeMessage[] = [];
280→        for (const sm of serverMessages) {
281→          if (sm.type === "relay") {
282→            rawMessages.push(sm.message);
283→          }
284→          const cm = relayChatMessage(agentId, sm);
285→          if (cm) chatMessages.push(cm);
286→        }
287→
288→        // Always replace local messages with server history (source of truth).
289→        // For active agents, live relay messages may have arrived before this
290→        // history replay — the replace ensures we don't lose or duplicate them.
291→        setAgents((prev) => {
292→          const existing = prev.get(agentId);
293→          if (!existing) {
294→            const next = new Map(prev);
295→            next.set(agentId, {
296→              status: "idle",
297→              messages: chatMessages,
298→              rawMessages,
299→              label: "",
300→              tmuxSession: null,
301→              createdAt: 0,
302→            });
303→            return next;
304→          }
305→          const next = new Map(prev);
306→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
307→          return next;
308→        });
309→
310→        processedCountRef.current.set(agentId, chatMessages.length);
311→        return;
312→      }
313→
314→      // ── history_cleared: wipe local messages for this agent ──
315→      if (data.type === "history_cleared") {
316→        updateAgent(data.agentId, (prev) => ({
317→          ...prev,
318→          messages: [],
319→          rawMessages: [],
320→        }));
321→        processedCountRef.current.set(data.agentId, 0);
322→        return;
323→      }
324→
325→      // ── cli_disconnected: show system message ──
326→      if (data.type === "cli_disconnected") {
327→        updateAgent(data.agentId, (prev) => ({
328→          ...prev,
329→          messages: [
330→            ...prev.messages,
331→            {
332→              id: nextId(),
333→              role: "system",
334→              content: "CLI session ended",
335→              timestamp: Date.now(),
336→            },
337→          ],
338→        }));
339→        return;
340→      }
341→
342→      // ── cli_connected: show system message ──
343→      if (data.type === "cli_connected") {
344→        updateAgent(data.agentId, (prev) => ({
345→          ...prev,
346→          messages: [
347→            ...prev.messages,
348→            {
349→              id: nextId(),
350→              role: "system",
351→              content: "CLI reconnected",
352→              timestamp: Date.now(),
353→            },
354→          ],
355→        }));
356→        return;
357→      }
358→
359→      // ── agent_list: reconcile sidebar state from server ──
360→      if (data.type === "agent_list") {
361→        const serverAgents = data.agents as AgentInfo[];
362→        setAgents((prev) => {
363→          const next = new Map(prev);
364→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
365→
366→          // Update or add agents from server
367→          for (const info of serverAgents) {
368→            const existing = next.get(info.agentId);
369→            if (existing) {
370→              next.set(info.agentId, {
371→                ...existing,
372→                status: info.status,
373→                tmuxSession: info.tmuxSession,
374→                label: info.label,
375→              });
376→            } else {
377→              next.set(info.agentId, {
378→                status: info.status,
379→                messages: [],
380→                rawMessages: [],
381→                label: info.label,
382→                tmuxSession: info.tmuxSession,
383→                createdAt: info.createdAt,
384→              });
385→            }
386→          }
387→
388→          // Remove agents no longer on the server
389→          for (const id of next.keys()) {
390→            if (!serverIds.has(id)) {
391→              next.delete(id);
392→            }
393→          }
394→
395→          return next;
396→        });
397→        setAgentOrder(serverAgents.map((a) => a.agentId));
398→
399→        // Auto-select the first agent on initial load when nothing is selected
400→        setActiveAgentId((prev) => {
401→          if (prev !== null) return prev;
402→          if (serverAgents.length === 0) return null;
403→          return serverAgents[0].agentId;
404→        });
405→        return;
406→      }
407→
408→      // ── spawned: auto-select the newly created agent ──
409→      if (data.type === "spawned") {
410→        setActiveAgentId(data.agentId);
411→        return;
412→      }
413→
414→      // ── status: update a specific agent's status ──
415→      if (data.type === "status") {
416→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
417→        return;
418→      }
419→
420→      // ── error: append to agent's message list ──
421→      if (data.type === "error") {
422→        updateAgent(data.agentId, (prev) => ({
423→          ...prev,
424→          messages: [
425→            ...prev.messages,
426→            {
427→              id: nextId(),
428→              role: "system",
429→              content: `Error: ${data.error}`,
430→              timestamp: Date.now(),
431→            },
432→          ],
433→        }));
434→        // Track processed count for dedup
435→        processedCountRef.current.set(
436→          data.agentId,
437→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
438→        );
439→        return;
440→      }
441→
442→      // ── relay: append claude message to agent's history ──
443→      if (data.type === "relay") {
444→        const agentId = data.agentId;
445→        const rawMsg = data.message;
446→        const chatMsg = relayChatMessage(agentId, data);
447→
448→        updateAgent(agentId, (prev) => ({
449→          ...prev,
450→          rawMessages: [...prev.rawMessages, rawMsg],
451→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
452→        }));
453→        if (chatMsg) {
454→          // Track processed count for dedup
455→          processedCountRef.current.set(
456→            agentId,
457→            (processedCountRef.current.get(agentId) ?? 0) + 1
458→          );
459→        }
460→        return;
461→      }
462→    };
463→  }, [updateAgent]);
464→
465→  useEffect(() => {
466→    closingRef.current = false;
467→    connect();
468→    return () => {
469→      closingRef.current = true;
470→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
471→      wsRef.current?.close();
472→    };
473→  }, [connect]);
474→
475→  const send = useCallback((data: object) => {
476→    if (wsRef.current?.readyState === WebSocket.OPEN) {
477→      wsRef.current.send(JSON.stringify(data));
478→    }
479→  }, []);
480→
481→  const spawnAgent = useCallback(
482→    (prompt: string) => {
483→      send({ type: "spawn", prompt });
484→    },
485→    [send]
486→  );
487→
488→  const sendMessage = useCallback(
489→    (content: string) => {
490→      if (!activeAgentId) return;
491→      // Optimistically add user message to local state
492→      updateAgent(activeAgentId, (prev) => ({
493→        ...prev,
494→        messages: [
495→          ...prev.messages,
496→          {
497→            id: nextId(),
498→            role: "user",
499→            content,
500→            timestamp: Date.now(),
501→          },
502→        ],
503→      }));
504→      send({ type: "send_message", agentId: activeAgentId, content });
505→    },
506→    [send, activeAgentId, updateAgent]
507→  );
508→
509→  const respondToControl = useCallback(
510→    (requestId: string, allow: boolean) => {
511→      if (!activeAgentId) return;
512→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
513→      updateAgent(activeAgentId, (prev) => ({
514→        ...prev,
515→        messages: prev.messages.map((m) =>
516→          m.controlRequest?.id === requestId
517→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
518→            : m
519→        ),
520→      }));
521→    },
522→    [send, activeAgentId, updateAgent]
523→  );
524→
525→  /** Respond to an AskUserQuestion control request with the user's selections. */
526→  const respondToUserQuestion = useCallback(
527→    (requestId: string, answers: Record<string, string>) => {
528→      if (!activeAgentId) return;
529→      send({
530→        type: "control_response",
531→        agentId: activeAgentId,
532→        request_id: requestId,
533→        allow: true,
534→        answers,
535→      });
536→      updateAgent(activeAgentId, (prev) => ({
537→        ...prev,
538→        messages: prev.messages.map((m) =>
539→          m.userQuestion?.requestId === requestId
540→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
541→            : m
542→        ),
543→      }));
544→    },
545→    [send, activeAgentId, updateAgent]
546→  );
547→
548→  // ── Agent management actions ──────────────────────────────────────────────
549→
550→  const killAgent = useCallback(
551→    (agentId: string) => {
552→      send({ type: "kill_agent", agentId });
553→    },
554→    [send]
555→  );
556→
557→  const deleteAgent = useCallback(
558→    (agentId: string) => {
559→      send({ type: "delete_agent", agentId });
560→      // Deselect if we just deleted the active agent
561→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
562→    },
563→    [send]
564→  );
565→
566→  const renameAgent = useCallback(
567→    (agentId: string, label: string) => {
568→      send({ type: "rename_agent", agentId, label });
569→    },
570→    [send]
571→  );
572→
573→  const clearHistory = useCallback(
574→    (agentId: string) => {
575→      send({ type: "clear_history", agentId });
576→    },
577→    [send]
578→  );
579→
580→  // ── Task actions ──────────────────────────────────────────────────────────
581→
582→  const createTask = useCallback(
583→    (title: string, description: string, priority: TaskPriority) => {
584→      send({ type: "create_task", title, description, priority });
585→    },
586→    [send]
587→  );
588→
589→  const updateTask = useCallback(
590→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
591→      send({ type: "update_task", taskId, updates });
592→    },
593→    [send]
594→  );
595→
596→  const deleteTask = useCallback(
597→    (taskId: string) => {
598→      send({ type: "delete_task", taskId });
599→    },
600→    [send]
601→  );
602→
603→  const delegateTask = useCallback(
604→    (taskId: string) => {
605→      send({ type: "delegate_task", taskId });
606→    },
607→    [send]
608→  );
609→
610→  // Derived values for the active agent
611→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
612→  const activeStatus = useMemo<AgentStatus>(
613→    () => activeAgent?.status ?? "idle",
614→    [activeAgent?.status]
615→  );
616→  const activeMessages = useMemo<ChatMessage[]>(
617→    () => activeAgent?.messages ?? [],
618→    [activeAgent?.messages]
619→  );
620→  const activeRawMessages = useMemo<ClaudeMessage[]>(
621→    () => activeAgent?.rawMessages ?? [],
622→    [activeAgent?.rawMessages]
623→  );
624→
625→  return {
626→    connected,
627→    agents,
628→    agentOrder,
629→    activeAgentId,
630→    setActiveAgentId,
631→    activeStatus,
632→    activeMessages,
633→    activeRawMessages,
634→    spawnAgent,
635→    sendMessage,
636→    respondToControl,
637→    respondToUserQuestion,
638→    killAgent,
639→    deleteAgent,
640→    renameAgent,
641→    clearHistory,
642→    tasks,
643→    createTask,
644→    updateTask,
645→    deleteTask,
646→    delegateTask,
647→  };
648→}
