  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 20→import { condenseMessages } from "@/lib/condense-messages";
 21→import { StatusBar } from "./status-bar";
 22→import { Message } from "./message";
 23→import { ControlRequest } from "./control-request";
 24→import { UserQuestion } from "./user-question";
 25→import { CondensedToolGroup } from "./condensed-tool-group";
 26→import { Button } from "@/components/ui/button";
 27→
 28→export function Chat({
 29→  connected,
 30→  status,
 31→  messages,
 32→  rawMessages,
 33→  onSendMessage,
 34→  onSpawnAgent,
 35→  onRespondToControl,
 36→  onRespondToUserQuestion,
 37→  showTasks,
 38→  onToggleTasks,
 39→  onToggleSidebar,
 40→}: {
 41→  connected: boolean;
 42→  status: AgentStatus;
 43→  messages: ChatMessage[];
 44→  rawMessages: ClaudeMessage[];
 45→  onSendMessage: (content: string) => void;
 46→  onSpawnAgent: (prompt: string) => void;
 47→  onRespondToControl: (requestId: string, allow: boolean) => void;
 48→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 49→  showTasks?: boolean;
 50→  onToggleTasks?: () => void;
 51→  onToggleSidebar?: () => void;
 52→}) {
 53→  const [input, setInput] = useState("");
 54→  const [showRaw, setShowRaw] = useState(false);
 55→  const scrollRef = useRef<HTMLDivElement>(null);
 56→
 57→  useEffect(() => {
 58→    scrollRef.current?.scrollTo({
 59→      top: scrollRef.current.scrollHeight,
 60→      behavior: "smooth",
 61→    });
 62→  }, [messages, rawMessages, showRaw]);
 63→
 64→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 65→  const isActive = status === "connected" || status === "thinking";
 66→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 67→
 68→  function handleSubmit(e: React.FormEvent) {
 69→    e.preventDefault();
 70→    const trimmed = input.trim();
 71→    if (!trimmed) return;
 72→
 73→    if (isActive) {
 74→      onSendMessage(trimmed);
 75→    } else {
 76→      onSpawnAgent(trimmed);
 77→    }
 78→    setInput("");
 79→  }
 80→
 81→  return (
 82→    <div className="flex h-full flex-col">
 83→      <StatusBar
 84→        connected={connected}
 85→        status={status}
 86→        showRaw={showRaw}
 87→        onToggleRaw={() => setShowRaw((v) => !v)}
 88→        showTasks={showTasks}
 89→        onToggleTasks={onToggleTasks}
 90→        onToggleSidebar={onToggleSidebar}
 91→      />
 92→
 93→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
 94→        {showRaw ? (
 95→          rawMessages.length === 0 ? (
 96→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
 97→              No raw messages yet
 98→            </div>
 99→          ) : (
100→            <div className="space-y-1">
101→              {rawMessages.map((msg, i) => (
102→                <RawMessage key={i} message={msg} index={i} />
103→              ))}
104→            </div>
